L25_1.m_Talk_ENG = "Is that you, Jun? What are you doing here?"
L25_1.m_Talk_TWN = "我還想說是誰咧，結果是朱恩？你在這裡幹嘛？"
L25_1.m_Talk_THA = "นั่นเขาเหรอจุน? มาทำอะไรที่นี่น่ะ?"
L25_1.m_Talk_VTN = "Có phải là em không, Jun? Sao em lại ở đây?"
L25_1.m_Talk_SCN = "我还以为是谁呢，原来是朱恩？你怎么会在这里？"
L25_1.m_Talk_DEU = "Jun? Was machst du denn hier?"
L25_1.m_Talk_FRA = "Hé mais c'est toi, Jun ? Qu'est-ce que tu fais ici ?"
L26_1 = {}
L26_1.m_CutScenKey_Talk = "ALPHA_ACT3_INTERLUDE2@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 3900304
L26_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_SURPRISE"
L26_1.m_CharStrID = "CHOI_ALPHA_NULL_SHORT"
L26_1.m_Pos = "C"
L26_1.m_Crash = 10
L26_1.m_Talk_KOREA = "으음? 아둔한 동생이야말로 왜 여기 온 거지?"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "へえ？　冴えない我が妹こそ、ここに何の用だ？"
L26_1.m_Talk_ENG = "Huh? What brings you here, little sister?"
L26_1.m_Talk_TWN = "嗯？我才想問笨妹妹怎麼會在這裡？"
L26_1.m_Talk_THA = "หา? เจ้ามาทำอะไรที่นี่กันน้องเล็ก?"
L26_1.m_Talk_VTN = "Huh? Điều gì đã đưa em đến đây thế, em gái?"
L26_1.m_Talk_SCN = "呃嗯？愚蠢的妹妹，我还想问你为什么来这呢！"
L26_1.m_Talk_DEU = "Huch? Selber! Was machst du hier, du Dumpfbacke?"
L26_1.m_Talk_FRA = "Je te retourne la question, PETITE sœur !"
