L29_1 = {}
L29_1.m_CutScenKey_Talk = "ALPHA_ACT3_INTERLUDE2@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 3900304
L29_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_SERIOUS"
L29_1.m_CharStrID = "SPEAR_ALPHA_NULL_SHORT"
L29_1.m_Pos = "R"
L29_1.m_Talk_KOREA = "큭……. 그 때 지지만 않았어도 내가 누나 하는 건데……."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "くう……あの時負けてなければ、私がお姉ちゃんだったのに……"
L29_1.m_Talk_ENG = "Krr...! If I hadn’t lost that fight, I would be calling him little brother right now...!"
L29_1.m_Talk_TWN = "可惡……要不是我那時候打輸，現在我可是你姊姊好嗎……"
L29_1.m_Talk_THA = "ฮึ่ม... ถ้าไม่ติดว่าสู้แพ้ ตอนนี้ฉันจะเรียกเขาว่าน้องชายเลยจริงๆ...!"
L29_1.m_Talk_VTN = "Krr...! Nếu mình không thua trận đó, bây giờ mình đã gọi hắn là em trai rồi...!"
L29_1.m_Talk_SCN = "呃……如果当时没有输给这家伙，我就是姐姐了……！"
L29_1.m_Talk_DEU = "Urgh ... Hätte ich damals nur nicht verloren, wäre ich die ältere von uns beiden ..."
L29_1.m_Talk_FRA = "Grr... Si seulement je n'avais pas perdu la dernière fois.... J'aurais pu être la grande sœur..."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "ALPHA_ACT3_INTERLUDE2@30#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 3900304
L30_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_HATE"
L30_1.m_CharStrID = "SPEAR_ALPHA_NULL_SHORT"
L30_1.m_Pos = "R"
L30_1.m_Talk_KOREA = "난 파사의 목소리가 여기로 가 달라고 해서 왔을 뿐이야."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "私は破邪の声に、ここに向かってほしいと言われて来ただけだよ。"
L30_1.m_Talk_ENG = "I’m here because the Voice of Evil Eradication told me to."
L30_1.m_Talk_TWN = "是破邪之聲叫我來這裡的！"
L30_1.m_Talk_THA = "ฉันมาที่นี่เพราะเสียงแห่งการกวาดล้างความชั่วร้ายบอกให้มา"
L30_1.m_Talk_VTN = "Em ở đây bởi vì Tiếng Nói Trừ Gian Diệt Ác bảo đến."
L30_1.m_Talk_SCN = "我是因为破邪之声的指引，才来这里的。"
L30_1.m_Talk_DEU = "Ich bin nur hier, weil die Stimme des Bekämpfers des Bösen es so wollte."
L30_1.m_Talk_FRA = "J'ai juste suivi la Voix de l'éradication du Mal."
