L32_1 = {}
L32_1.m_CutScenKey_Talk = "ALPHA_ACT3_INTERLUDE2@32#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 3900304
L32_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_HATE"
L32_1.m_CharStrID = "SPEAR_ALPHA_NULL_SHORT"
L32_1.m_Pos = "C"
L32_1.m_Talk_KOREA = "그러는 너희야말로 여기서 뭔가 꾸미고 있는 건 아니겠지?"
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "あんたたちこそ、ここで何か企んでるわけじゃないよね？"
L32_1.m_Talk_ENG = "You guys aren’t scheming of doing something here, are you?"
L32_1.m_Talk_TWN = "倒是你們，不會是想在這裡作怪吧？"
L32_1.m_Talk_THA = "พวกเธอคงไม่ได้วางแผนจะมาทำอะไรที่นี่กันหรอก ใช่มั้ย?"
L32_1.m_Talk_VTN = "Mấy người không ủ mưu gì đó đấy chứ?"
L32_1.m_Talk_SCN = "不过，你们不会是在这搞什么阴谋吧？"
L32_1.m_Talk_DEU = "Das kann ich aber zurückfragen. Heckt ihr hier etwas aus?"
L32_1.m_Talk_FRA = "Tu es sûre que tu n'es pas plutôt en train de manigancer quelque chose ?"
L33_1 = {}
L33_1.m_CutScenKey_Talk = "ALPHA_ACT3_INTERLUDE2@33#Talk"
