L34_1 = {}
L35_1 = 2
L36_1 = 0.15
L34_1[1] = L35_1
L34_1[2] = L36_1
L33_1.m_Bounce = L34_1
L33_1.m_Talk_KOREA = "만약 그렇다면 가만히 있지 않겠어!"
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "もしそうなら、ただじゃ済まないからね！"
L33_1.m_Talk_ENG = "If you are, then I will not allow it!"
L33_1.m_Talk_TWN = "要是被我逮到，我可不會放過你們！"
L33_1.m_Talk_THA = "ไม่งั้นละก็ ฉันไม่ยอมให้ทำหรอกนะ!"
L33_1.m_Talk_VTN = "Nếu là vậy, tôi sẽ không cho phép đâu!"
L33_1.m_Talk_SCN = "如果是这样，我绝对不会袖手旁观！"
L33_1.m_Talk_DEU = "Falls ja, kann ich kein Auge zudrücken!"
L33_1.m_Talk_FRA = "Si c'est le cas, je ne te laisserai pas faire !"
