L36_1.m_Face = "UNIT_SERIOUS"
L36_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L36_1.m_Pos = "L"
L36_1.m_Crash = 10
L36_1.m_Talk_KOREA = "흥. 감찰과에서 정직 처분 받은 꼬맹이는 하나도 안 무섭네요."
L36_1.m_fTalkTime = 0.03
L36_1.m_Talk_JPN = "ふん、監察課から停職処分を受けたチビなんて全然怖くないもん。"
L36_1.m_Talk_ENG = "Hmph. Like we’d be scared of a punk who got suspended in Investigations."
L37_1 = "哼，被監察科停止處分的小鬼有什麼好怕的！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฮึ่ม อย่างกับเราจะกลัวคนปากแก๋วที่โดนแขวนในฝ่ายตรวจสอบอย่างนั้นแหละ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Hứ. Làm như chúng tôi sợ một nhóc ngố tàu bị Ban Điều Tra đình chỉ vậy."
L36_1.m_Talk_VTN = L37_1
L37_1 = "哼。被监察科停职处分的小不点，我才不会怕呢。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Pah. Keiner hat Angst vor einem Knirps, der von der Inspektionsabteilung suspendiert wurde."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Pff. Tu crois qu'une gamine envoyée par le Bureau d'inspection nous fait peur ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "ALPHA_ACT3_INTERLUDE2@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900304
L37_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_SERIOUS"
L37_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L37_1.m_Pos = "R"
L38_1 = "어떻게 할까요, 리더? 우선 한 발 물러서서 상황을 구경하는 걸 추천합니다만."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "どうしましょうか、リーダー？　まずは一歩下がって様子を見ることを\nお勧めしますが。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "What should we do, Leader? I suggest we take a step back and watch how this plays out."
L37_1.m_Talk_ENG = L38_1
L38_1 = "老大，現在該怎麼辦？我個人是建議先觀察一下情況。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เอาไงดีคะท่านผู้นำ? ฉันแนะนำให้ถอยสักก้าวแล้วรอดูท่าทีก่อนดีกว่า"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chúng ta nên làm gì đây, Thủ Lĩnh? Tôi nghĩ chúng ta nên lùi lại một chút và xem việc này diễn ra thế nào."
L37_1.m_Talk_VTN = L38_1
L38_1 = "该怎么办，队长？我建议还是先撤退，静观其变。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Was nun, Anführerin? Ich empfehle, dass wir einen Schritt zurücktreten und die Lage gemütlich beobachten."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Que comptez-vous faire, chef ? Je vous suggère d'attendre pour analyser la situation."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
