L40_1.m_Face = "UNIT_SERIOUS"
L40_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "아뇨. 지금으로서는 범인에 대한 단서가 더 중요해요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "いいえ。今は犯人に関する手掛かりが最重要です。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "No. Right now, the clue is more important."
L40_1.m_Talk_ENG = L41_1
L41_1 = "不，現在更重要的是有關犯人的線索。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ไม่ค่ะ ตอนนี้เบาะแสสำคัญกว่า"
L40_1.m_Talk_THA = L41_1
L41_1 = "Không. Ngay bây giờ, manh mối quan trọng hơn."
L40_1.m_Talk_VTN = L41_1
L41_1 = "不。现在对我们来说，凶手的线索更重要。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Nein, im Moment ist für uns der Anhaltspunkt über den Täter wichtiger."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Non. Je dois absolument trouver des preuves."
L40_1.m_Talk_FRA = L41_1
