L43_1 = "ALPHA_ACT3_INTERLUDE2@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3900304
L42_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_PRIDE"
L42_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "별일 없을 거예요, 초원 씨. 다른 분들이 위험에 처해도 제가 대처해 드릴게요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "心配しないでください、ナオさん。\n他の方々が危険に晒されても、私が対処します。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Everything will be fine, Chowon. If something happens, I’ll protect you and everyone else."
L42_1.m_Talk_ENG = L43_1
L43_1 = "不會有事的，萬一其他人發生危險，我也可以應付的！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ไม่เป็นไรหรอกค่ะโชวอน ถ้าเกิดอะไรขึ้น ฉันจะปกป้องคุณกับทุกคนเอง"
L42_1.m_Talk_THA = L43_1
L43_1 = "Mọi chuyện sẽ ổn thôi, Chowon. Nếu có chuyện gì xảy ra, tôi sẽ bảo vệ mọi người."
L42_1.m_Talk_VTN = L43_1
L43_1 = "不会有事的，桃沢梨绘。如果你们陷入危险，我会救你们的。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Es wird schon gutgehen, Chowon. Ich werde bereit sein, falls die anderen in Gefahr geraten."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Pas d'inquiétude, Chowon. Je viendrai immédiatement s'il vous arrive quelque chose."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ALPHA_ACT3_INTERLUDE2@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
