L43_1.m_Pos = "C"
L44_1 = "……알겠습니다. 고용주가 그렇게 말씀하시면 답이 없긴 하죠."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "……わかりました。クライアントにそう言われたら仕方ありませんね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "...Okay. If that’s what you wish..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "……好吧，既然雇主這麼說，那我也沒什麼好說的。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "...เอางั้นก็เอาค่ะ..."
L43_1.m_Talk_THA = L44_1
L44_1 = "...Được thôi. Nếu đó là điều cô muốn..."
L43_1.m_Talk_VTN = L44_1
L44_1 = "……知道了。既然你这么说，那我选择服从命令。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "... Verstanden. Wenn das mein Arbeitgeber sagt, dann ist es wohl so."
L43_1.m_Talk_DEU = L44_1
L44_1 = "... Très bien. Je ne peux pas aller à l'encontre de mon employeur."
L43_1.m_Talk_FRA = L44_1
