L50_1.m_Pos = "R"
L51_1 = "겉으로 보기에는. 하지만 안경에 비치는 구조는……."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "見た目はそうでしょうね。でもメガネに映った構造は……"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Or it may seem. But from what I see through my glasses..."
L50_1.m_Talk_ENG = L51_1
L51_1 = "那只是表象而已，我的眼鏡反射出來的結構……"
L50_1.m_Talk_TWN = L51_1
L51_1 = "หรืออาจแค่ดูเป็นแบบนั้น เพราะที่ฉันเห็นผ่านแว่นนี่..."
L50_1.m_Talk_THA = L51_1
L51_1 = "Hoặc có vẻ là thế. Nhưng từ những gì tôi nhìn thấy qua kính của mình..."
L50_1.m_Talk_VTN = L51_1
L51_1 = "虽然表面上看起来是这样，但从眼镜中观察到的房间构造……"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Auf den ersten Blick, ja. Aber die Struktur, die auf der Brille reflektiert ..."
L50_1.m_Talk_DEU = L51_1
L51_1 = "À l'œil nu peut-être. Mais pas avec mes lunettes..."
L50_1.m_Talk_FRA = L51_1
