L23_1 = "이 몸은 벌써 클론에 대한 단서를 확보했느니라."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "私はすでにクローンに関する手掛かりを確保できたわ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I already collected the clue about the clone."
L22_1.m_Talk_ENG = L23_1
L23_1 = "我已經找到有關複製人的線索！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันเอาข้อมูลเกี่ยวกับร่างโคลนมาแล้ว"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cô đã thu thập manh mối về bản sao."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我可是找到了关于克隆体的线索。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Meine Wenigkeit hat bereits einen Anhaltspunkt zum Klon gesichert."
L22_1.m_Talk_DEU = L23_1
