L24_1 = "UNIT_LAUGH"
L23_1.m_Face = L24_1
L23_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L23_1.m_Pos = "C"
L23_1.m_Crash = 10
L24_1 = "또 지아의 곁에서 지아를 기만하던 범인을 잡아냈지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そして、ユイちゃんの側でユイちゃんを騙していた犯人を捕まえたのよ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Also, I caught the suspect behind all of it."
L23_1.m_Talk_ENG = L24_1
L24_1 = "還揪出在你身邊欺騙你的犯人！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แถมยังจับผู้ต้องสงสัยเบื้องหลังเรื่องทั้งหมดได้ด้วย"
L23_1.m_Talk_THA = L24_1
L24_1 = "Ngoài ra, cô đã bắt được kẻ tình nghi đằng sau tất cả mọi chuyện."
L23_1.m_Talk_VTN = L24_1
L24_1 = "而且还抓到了在小佳身边欺骗小佳的凶手。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Außerdem habe ich den Täter gefangen, der Jia direkt neben ihr hinters Licht führte."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Et pour couronner le tout, j'ai même démasquée la coupable !"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "ALPHA_ACT3_INTERLUDE2@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3900304
L24_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_SURPRISE"
L24_1.m_CharStrID = "CHOI_ALPHA_NULL_SHORT"
L24_1.m_Pos = "C"
L25_1 = "범인……? 실장이 범인이라고?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "犯人……？　室長が犯人だと？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "The suspect...? You mean that Chief was the one behind it?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "犯人……？你說室長就是犯人？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ผู้ต้องสงสัย...? หมายถึงหัวหน้าอยู่เบื้องหลังเรื่องนี้รึ?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Nghi phạm...? Ý là Trưởng Phòng đứng sau mọi chuyện ư?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "凶手……？你说室长是凶手？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Den Täter ...? Die Direktorin ist der Täter?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "La coupable... ? Tu veux dire, Jin ?!"
L24_1.m_Talk_FRA = L25_1
