L26_1.m_Face = "UNIT_HATE"
L26_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "……그렇다면 세실리아 씨가 마저 해결해 주세요. 이진 언니는 저와 더 이상 상관없는 사람이니까요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "……それならセシリアさんが最後まで解決してください。\nホノカさんはもう私とは関係ない人ですから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Then I want you to take care of it, Cecilia. She and I have nothing to do with each other anymore."
L26_1.m_Talk_ENG = L27_1
L27_1 = "……那就請你動手處理吧，李珍姐和我已經沒有關係了。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ถ้าอย่างนั้นฉันก็อยากให้คุณจัดการทีค่ะเซซิเลีย เธอกับฉันไม่มีอะไรเกี่ยวข้องกันอีกแล้ว"
L26_1.m_Talk_THA = L27_1
L27_1 = "Vậy thì cô cứ tự mình xử trí, Cecilia. Cháu và cô ấy không còn liên quan gì đến nhau nữa."
L26_1.m_Talk_VTN = L27_1
L27_1 = "……那么就交给赛西莉亚你来解决吧。因为李珍姐姐已经是与我无关的人了。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "... Dann kümmern Sie sich bitte darum, Cecilia. Denn Lee Jin hat mit mir nichts mehr zu tun."
L26_1.m_Talk_DEU = L27_1
L27_1 = "... Hé bien vous n'avez qu'à terminer le travail vous-même, Cecilia. Les problèmes de Jin ne me concernent plus."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
