L28_1[2] = L30_1
L27_1.m_Bounce = L28_1
L28_1 = "리더! 저 상황을 보고도 왜 자꾸 그래?!"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "リーダー！　あの状況を見てそんなことが言えるの！？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Leader! How can you say that after seeing all this?!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "老大！你怎麼現在還說這種話！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ท่านผู้นำคะ! เห็นแบบนี้แล้วยังพูดแบบนั้นได้ยังไงคะ?!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Thủ Lĩnh! Sao chị nỡ nói thế sau nhìn thấy tất cả những điều này?!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "队长！现在这种情况，你怎么可以说这种话？！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Aber, Anführerin! Du siehst doch was los ist, was hast du denn?!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Chef ! Mais comment pouvez-vous dire ça ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
