L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L29_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L29_1.m_Pos = "C"
L30_1 = "후후, 경찰에게 넘기고 싶은 마음은 굴뚝 같다만, 네가 꼭 봐야 할 걸 찾아서 말이다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "フフ、警察に身柄を渡したい気持ちは山々だけど、\nぜひ君に見てほしい物を見つけてね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Fu fu. I wanted to turn her in, but I thought you might want to see this before I did."
L29_1.m_Talk_ENG = L30_1
L30_1 = "呵呵，雖然我也很想趕快把她交給警察，但你必須看一下這個。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "หุหุ ฉันก็อยากส่งเธอให้ตำรวจอยู่หรอกนะ แต่คิดว่าเธอน่าจะอยากเห็นนี่ก่อน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Fu fu. Cô đã muốn giao nộp cô ta, nhưng cô nghĩ cháu có thể muốn thấy điều này trước."
L29_1.m_Talk_VTN = L30_1
L30_1 = "呼呼呼，虽然我很想直接交给警察，但是有一样东西必须让你看一下。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Hoho, ich würde sie ja liebend gerne der Polizei übergeben, aber du musst dir etwas ansehen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ha ha. Je voulais l'amener au commissariat mais il fallait que je te montre quelque chose avant."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
