L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3900304
L32_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L32_1.m_Pos = "L"
L33_1 = "저 여자가 가지고 있던 보고서다. 그 때 우리가 본 클론에 대해 자세히 적혀 있더군."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あの女が持っていた報告書よ。あの時、私たちが見たクローンについて\n詳しく書かれていたの。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "This is the report she had with her. It has all the details about the clone we saw."
L32_1.m_Talk_ENG = L33_1
L33_1 = "這是在她身上找到的報告，裡面清楚記錄著複製人的資料！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "นี่คือรายงานที่เธอเอามาด้วย มันมีรายละเอียดทั้งหมดของร่างโคลนที่เราเจอ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đây là bản báo cáo mà cô ấy đã đem theo. Nó có tất cả thông tin chi tiết về bản sao mà chúng ta đã thấy."
L32_1.m_Talk_VTN = L33_1
L33_1 = "就是那个女人带着的报告书。上面详细记录了当时我们看到的克隆体的信息。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das ist der Bericht, den diese Frau bei sich hatte. Da steht mehr drin über den Klon, den wir sahen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Les documents qu'elle avait sur elle. Il y a des détails sur le clone que nous avons vu la dernière fois."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
