L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3900304
L36_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
