L36_1.m_Pos = "C"
L36_1.m_Crash = 10
L37_1 = "보고서가 실장님이 범인이란 증거라고? 말도 안 돼!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "その報告書が室長が犯人だという証拠だって？　あり得ない！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "That report is proof that Chief is the culprit? Don’t kid yourself!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "光憑那個報告就說室長是犯人？會不會太誇張！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "รายงานนั่นคือข้อพิสูจน์ว่าหัวหน้าเป็นคนร้ายเหรอ? อย่าหลอนไปหน่อยเลย!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Báo cáo đó là bằng chứng cho thấy Trưởng Phòng là thủ phạm sao? Đừng có đùa chứ!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "你说报告书就是证明室长是凶手的证据？别胡扯了！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Der Bericht soll beweisen, dass die Direktorin der Täter sei? Das ist doch absurd!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est ça, la preuve que Jin est coupable ? C'est totalement absurde !"
L36_1.m_Talk_FRA = L37_1
