L42_1 = 0.15
L40_1[1] = L41_1
L40_1[2] = L42_1
L39_1.m_Bounce = L40_1
L40_1 = "당장 실장님 안 풀어 주면 언니한테 혼난다?!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "今すぐ室長を解放しないならお姉ちゃん、怒るよ！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You let her go right now, or I’m gonna spank you!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "你還不快點把室長鬆開，姊姊要生氣囉！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ปล่อยเธอเดี๋ยวนี้เลยนะ ไม่งั้นฉันจับตีก้นแน่!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hãy thả chị ấy ra ngay, nếu không tôi sẽ cho cô biết tay!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "马上放开室长，不然会让你尝到厉害的！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Lass die Direktorin sofort gehen, sonst gibt es Saures!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Libère-la sinon tu vas passer un sale quart d'heure !"
L39_1.m_Talk_FRA = L40_1
