L40_1.m_Pos = "R"
L41_1 = "흥. 상황 파악도 안 될 만큼 머리가 나쁘면 빠져 있어라."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ふん、状況把握もできないくらい頭が悪い子は黙ってなさい。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Hmph. If you don’t see what’s going on, then I suggest you back off."
L40_1.m_Talk_ENG = L41_1
L41_1 = "哼，搞不清楚狀況的笨蛋，你哪邊涼快哪邊去吧！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เฮอะ ถ้าไม่รู้หินรู้แดดอะไรก็ขอแนะนำให้ถอยไปดีกว่านะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Hừm. Nếu nhóc không hiểu chuyện gì đang xảy ra, ta khuyên nhóc hãy lùi lại."
L40_1.m_Talk_VTN = L41_1
L41_1 = "哼。如果你愚蠢到不能理解现在的情况，就滚一边去吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Hmpf. Halt dich raus, wenn du zu doof bist, um die Lage zu blicken."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Si tu es trop stupide pour comprendre la situation, ne t'en mêle pas !"
L40_1.m_Talk_FRA = L41_1
