L46_1 = {}
L47_1 = "ALPHA_ACT3_INTERLUDE2@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3900304
L46_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "LEEJIN_ALPHA_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L46_1.m_bCharHologramEffect = true
L47_1 = "아가씨에게 무언가 기묘한 재능이 있다는 건 인정하겠습니다만……. 그저 그뿐입니다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "お嬢様に何か不思議な才能があることは認めますが……ただ、それだけです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I will admit that she has an uncanny ability... But that’s all there is to it."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我承認小姐是有特殊的能力沒錯……但就僅此而已。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฉันยอมรับนะคะว่าคุณเจียมีความสามารถน่าอัศจรรย์... แต่ก็แค่นั้นแหละค่ะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi phải thừa nhận rằng tiểu thư Jia có một khả năng kỳ lạ... Nhưng chỉ vậy mà thôi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "小姐的确有某种奇妙的才能，这一点我不得不承认……但也仅此而已。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich gestehe ein, dass sie eine mystische Macht besitzt ... Aber das war‘s auch schon."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Elle a bien certaines dispositions, mais... Ça s'arrête là."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "ALPHA_ACT3_INTERLUDE2@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3900304
L47_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_SERIOUS"
L48_1 = "LEEJIN_ALPHA_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L47_1.m_bCharHologramEffect = true
L48_1 = "그 외에는 부모 말 잘 듣는 아이일 뿐이죠. 공략할 수 있는 부분은 다른 또래들보다 더 많은 편입니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "それ以外は、親の言うことをよく聞く子どもでしかありません。\nむしろ、付け込める要素は同年代の子どもたちよりも多いほうです。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Other than that, she’s just a girl who listens to her parents. However, she does seem to be more vulnerable than her peers."
L47_1.m_Talk_ENG = L48_1
L48_1 = "除此之外，小姐不過就只是個聽話的孩子。 她比其他同年紀的孩子都還沒有心機。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "นอกนั้นแล้ว เธอก็แค่เด็กผู้หญิงที่เชื่อฟังพ่อแม่ แต่ถึงยังไงก็ดูเปราะบางกว่าเด็กรุ่นราวคราวเดียวกัน"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ngoài sự kỳ lạ ấy ra, cô ấy chỉ là một cô gái nghe lời cha mẹ. Tuy nhiên, cô ấy dường như dễ bị tổn thương hơn những người đồng trang lứa."
L47_1.m_Talk_VTN = L48_1
L48_1 = "除此之外，小姐就是个听家长话的乖乖女。能被人所利用的弱点，甚至比同龄人还要多。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Davon abgesehen ist sie auch nur ein Mädchen, das ihren Eltern gehorcht. Sie hat aber mehr Potenzial als gleichaltrige."
L47_1.m_Talk_DEU = L48_1
L48_1 = "C'est une jeune fille qui écoute ses parents, voilà tout. Nombreux sont ceux qui pourraient abuser de sa crédulité..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
