L50_1 = "ALPHA_ACT3_INTERLUDE2@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3900304
L49_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L49_1.m_CharStrID = L50_1
L50_1 = "흐음……. 뭔가 잊은 것 같군, 이 실장."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ふむ……何か忘れていないか、シノザキ室長。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Hmm... I think you’re forgetting something, Chief Lee."
L49_1.m_Talk_ENG = L50_1
L50_1 = "嗯……李室長，你是不是忘了？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "อืมม... ผมว่าคุณลืมอะไรไปนะ หัวหน้าลี"
L49_1.m_Talk_THA = L50_1
L50_1 = "hừm... Tôi nghĩ cô đang quên gì đó đấy, Trưởng Phòng Lee ạ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "嗯……看来你忘了一件事，李室长。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Hmm ... Du scheinst, etwas vergessen zu haben, Direktorin Lee."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Hmm... Je crois que tu oublies quelque chose, Jin."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "ALPHA_ACT3_INTERLUDE2@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3900304
L50_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L50_1.m_CharStrID = L51_1
L51_1 = "나는 기회가 생겼을 때 그 괴물을 없애라고 자네를 이노베이션에 심어 둔 걸세."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "私はあの化け物を消す機会を窺うために、\n君をイノベーションに潜入させたつもりだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I put you in Innovation so that you can get rid of her when the opportunity arises."
L50_1.m_Talk_ENG = L51_1
L51_1 = "當初我派你去改革時，是要你一有機會就把那個怪物除掉。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ผมเอาคุณไปอยู่ในอินโนเวชั่นเพื่อให้กำจัดเธอเมื่อโอกาสสุกงอม"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi cài cô vào Cải Cách để cô loại bỏ cô ta khi có cơ hội."
L50_1.m_Talk_VTN = L51_1
L51_1 = "我把你安排到阿尔法崔克斯改革，是想让你找机会除掉那个怪胎。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich habe dich in die Innovation gesteckt, damit du das Monster bei Gelegenheit beseitigst."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Si je t'ai affectée à ce poste au sein d'Innovation, c'est pour pouvoir éliminer ce monstre à la moindre occasion."
L50_1.m_Talk_FRA = L51_1
