L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3900304
L1_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "EXECUTIVE_NPC_ALPHA_MAJOR"
L1_1.m_CharStrID = L2_1
L2_1 = "내가 언제 자네에게 베이비시터 노릇까지 하라고 했던가?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "君に子守りの役まで頼んだおぼえは無いが？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Did I put you on babysitting duties?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "我是叫你去當保母的嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "จำไม่ได้นะว่าผมให้คุณไปเป็นพี่เลี้ยงเด็ก หรือผมสั่ง?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi nhớ là mình đâu có giao cho cô nhiệm vụ trông trẻ đâu nhỉ?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "没让你兼职当她的保姆吧？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wann hatte ich dich zum Babysitten beauftragt?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je ne t'ai jamais demandé de jouer la baby-sitter, si ?"
L1_1.m_Talk_FRA = L2_1
