L4_1 = "ALPHA_ACT3_INTERLUDE2@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3900304
L3_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SERIOUS"
L3_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L3_1.m_Pos = "C"
L4_1 = "이건 이 여자와 부회장이 나눈 대화의 녹취록이다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "これはこの女と副会長が交わした会話の録音データよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Here’s a transcript of the conversation she had with the Vice Chairman."
L3_1.m_Talk_ENG = L4_1
L4_1 = "這是那女的和副會長的對話錄音。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "นี่คือถอดเทปบทสนทนาระหว่างเธอกับรองประธาน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đây là bản ghi về cuộc trò chuyện của cô ấy với Phó Chủ Tịch."
L3_1.m_Talk_VTN = L4_1
L4_1 = "这是那个女人和副会长的通话录音。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Das ist das Transkript des Gesprächs zwischen ihr und dem Vizepräsidenten."
L3_1.m_Talk_DEU = L4_1
L4_1 = "C'est un enregistrement d'une discussion avec le vice-président."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "ALPHA_ACT3_INTERLUDE2@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3900304
L4_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L4_1.m_Pos = "C"
L5_1 = "이 여자는 처음부터 여차하면 지아를 죽이려고 부회장이 심어 둔 끄나풀이야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "この女は最初から、いざとなったらユイちゃんを殺せるよう副会長が潜入させたスパイなの。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "All this time, she was a mole placed by the Vice Chairman to kill Jia."
L4_1.m_Talk_ENG = L5_1
L5_1 = "這女的是副會長安排在小佳身邊的內賊，打算找機會要了小佳的命！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เธอเป็นหนอนบ่อนไส้ที่รองประธานส่งมาฆ่าเจียแต่ไหนแต่ไรแล้ว"
L4_1.m_Talk_THA = L5_1
L5_1 = "Suốt thời gian qua, cô ấy là kẻ mà Phó Chủ Tịch sắp xếp để ẩn núp bên cạnh và giết Jia."
L4_1.m_Talk_VTN = L5_1
L5_1 = "那个女人从一开始就是为了杀掉小佳，而潜伏在她身边的副会长的走狗。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Sie ist ein Maulwurf des Vizepräsidenten, die Jia bei Gelegenheit töten sollte."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Depuis le début, Jin est aux ordres du vice-président. Elle devait pouvoir t'éliminer à tout moment, quand il le jugerait nécessaire."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "ALPHA_ACT3_INTERLUDE2@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3900304
L5_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_IDLE"
L5_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L5_1.m_Pos = "C"
L6_1 = "영특한 지아는 그걸 알면서도 용서해 줬지."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "賢いユイちゃんはそれを知りながら許してやった。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Clever Jia knew about it all this time, and forgave her."
L5_1.m_Talk_ENG = L6_1
L6_1 = "聰明如小佳，雖然很清楚她的目的，卻還是寬恕她。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เจียคนเก่งรู้เรื่องนี้มาตลอด แต่ก็ยังยกโทษให้"
L5_1.m_Talk_THA = L6_1
L6_1 = "Jia thông minh đã luôn biết điều đó, và đã tha thứ cho cô ấy."
L5_1.m_Talk_VTN = L6_1
L6_1 = "聪明的小佳虽然早就知道了真相，但还是原谅了她。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Unsere schlaue Jia wusste das, hat ihr aber verziehen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais Jia la perspicace l'a pardonnée."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "ALPHA_ACT3_INTERLUDE2@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3900304
L6_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L6_1.m_Pos = "C"
L6_1.m_Crash = 10
L7_1 = "내 말이 틀리니, 지아야?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そうでしょう、ユイちゃん？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Am I wrong, Jia?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "我有說錯嗎，小佳？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ใช่มั้ยเจีย?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô có nói sai không, Jia?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "我说的没错吧，小佳？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Habe ich unrecht, Jia?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Est-ce que je me trompe ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "ALPHA_ACT3_INTERLUDE2@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
