L11_1 = "ALPHA_ACT3_INTERLUDE2@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3900304
L10_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_SURPRISE"
L10_1.m_CharStrID = "SPEAR_ALPHA_NULL_SHORT"
L10_1.m_Pos = "R"
L11_1 = "저 아줌마가 부회장이랑 같은 편이었다고?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あのおばさんが副会長の手下だったと？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "So she was in it with the Vice Chairman?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "那個大嬸和副會長是同一國的喔？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "สรุปคือผู้หญิงคนนั้นอยู่ในรถกับรองประธานงั้นรึ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Vậy cô ta đã cùng phe với Phó Chủ tịch à?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "你说那个阿姨是和副会长一伙的？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Diese Frau steckte mit dem Vizepräsidenten unter einer Decke?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Tu dis que cette vieille était du côté du vice-président ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "ALPHA_ACT3_INTERLUDE2@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3900304
L11_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "SPEAR_ALPHA_NULL_SHORT"
L11_1.m_Pos = "R"
L11_1.m_Crash = 10
L12_1 = "그럼 왜 부회장이 살해당한 거야?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "じゃあ、なんで副会長は殺されたの？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Then why was he assassinated?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "那副會長怎麼會被殺？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แล้วทำไมเขาถูกลอบสังหารล่ะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Vậy tại sao ông ta bị ám sát?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "那为什么要杀害副会长？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Warum wurde der Vizepräsident dann ermordet?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Alors pourquoi est-il mort ?"
L11_1.m_Talk_FRA = L12_1
