L14_1 = "ALPHA_ACT3_INTERLUDE2@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3900304
L13_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SERIOUS"
L13_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L13_1.m_Pos = "C"
L13_1.m_Crash = 10
L14_1 = "당연히 내분이 있었겠지. 아마 이 보고서 탓에 말이다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "内紛があったに違いないわ。おそらくこの報告書のせいでね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Why do you think? It's because of internal conflicts, or possibly because of this report."
L13_1.m_Talk_ENG = L14_1
L14_1 = "當然是因為內鬨吧？可能跟這份報告有關。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "คิดว่าเพราะอะไรล่ะ? ก็เพราะความขัดแย้งภายใน ไม่ก็อาจเพราะรายงานนี่"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhóc nghĩ là tại sao? Đó là do xung đột nội bộ hoặc có thể do báo cáo này."
L13_1.m_Talk_VTN = L14_1
L14_1 = "当然是发生了内部纠纷。可能是因为这个报告书吧。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Da gab es ganz klar interne Konflikte. Wohl wegen dieses Berichts."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Surement un litige interne ? Où peut-être à cause de ce rapport ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "ALPHA_ACT3_INTERLUDE2@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3900304
L14_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L14_1.m_Pos = "C"
L15_1 = "뻔뻔하게 지아 시중을 드는 척 하던 여자가 자기 주인이라고 물지 못할 법 있나?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "図々しくユイちゃんに仕えてるふりをしていた女だから、\n自分の主に歯向かうのもあり得る話でしょ？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Is there any reason she wouldn't bite her owner's hand? She's clearly not ashamed of pretending to serve Jia."
L14_1.m_Talk_ENG = L15_1
L15_1 = "她都可以裝作一副沒事的樣子待在小佳身邊，就算反咬自己的主人也不意外吧？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "จะมีเหตุผลอะไรให้เธอแว้งกัดเจ้าของตัวเองได้อีก? เธอไม่อายด้วยซ้ำที่มาแกล้งทำเป็นรับใช้เจีย"
L14_1.m_Talk_THA = L15_1
L15_1 = "Có lý do nào khiến cô ấy không thể cắn ngược lại chủ nhân của mình chữ? Cô ta rõ ràng không hề ăn năn khi giả vờ phục vụ Jia."
L14_1.m_Talk_VTN = L15_1
L15_1 = "那个女人能够一直戴着面具辅佐小佳，难道就不会反咬自己的主人吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Diese Frau ist so hinterhältig, wie man bei Jia sah, dass sie ihren Meister verraten würde."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Si elle a fait semblant d'être au service de Jia tout ce temps, elle doit être tout à fait capable de trahir son maître !"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
