L16_1.m_Pos = "C"
L16_1.m_Crash = 10
L17_1 = "결국 심문하면 다 불게 되어 있어."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "尋問すればすぐ自白するでしょうね。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "We’ll know everything after the interrogation."
L16_1.m_Talk_ENG = L17_1
L17_1 = "只要拷問她就會全盤托出吧？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ทั้งหมดจะกระจ่างหลังสอบปากคำ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Chúng ta sẽ biết mọi thứ sau cuộc thẩm vấn."
L16_1.m_Talk_VTN = L17_1
L17_1 = "想要真相大白的话，就亲自审问一下怎么样？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Sie wird schon singen, wenn man sie foltert."
L16_1.m_Talk_DEU = L17_1
L17_1 = "De toute façon, la vérité finira par éclater lors de l'interrogatoire."
L16_1.m_Talk_FRA = L17_1
