L17_1.m_Pos = "C"
L18_1 = "마침 블랙 네트워크에서 아주 특별한 자백제를 구해 왔으니……."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ちょうどブラックネットワークで特別な自白剤を手に入れたから……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I even found a special truth serum on the Dark Network to give her..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "剛好我這裡有從黑色網路找到的吐實劑……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "แถมฉันยังเจอเซรัมพูดความจริงจากดาร์กเน็ตเวิร์กมาฉีดให้เธอด้วย..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Ta thậm chí còn tìm thấy một huyết thanh sự thật trên Mạng Đen để cho cô ta dùng..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "我正好有在黑色网络买到的非常特别的吐真剂……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich habe zufällig einen speziellen Wahrheitstrank aus dem Schattennetz mit ..."
L17_1.m_Talk_DEU = L18_1
L18_1 = "J'ai récupéré un sérum de vérité très spécial sur le dark net."
L17_1.m_Talk_FRA = L18_1
