L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3900304
L19_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_IDLE"
L19_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "그 연기, 계속 하실 건가요? <color=#ffd34c>고모님</color>?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "その演技、いつまで続けるつもりですか？　<color=#ffd34c>叔母様</color>？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "But how much longer are you going to keep this up, <color=#ffd34c>Auntie</color>?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "你打算繼續演下去嗎？<color=#ffd34c>姑姑</color>？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "แต่<color=#ffd34c>น้า</color>จะทำแบบนี้ไปอีกนานแค่ไหนคะ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhưng <color=#ffd34c>cô</color> này, cô định tiếp tục chuyện này bao lâu nữa?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "还要继续演戏吗？<color=#ffd34c>姑姑</color>？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Aber wie lange wollen sie noch weiter diese Rolle spielen, <color=#ffd34c>Tante</color>?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Vous avez fini votre numéro ? Chère <color=#ffd34c>tante</color> ?"
L19_1.m_Talk_FRA = L20_1
