L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3900304
L21_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "UNIT_LAUGH"
L21_1.m_Face = L22_1
L21_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "아, 헷갈리시면 이렇게 불러드릴까요?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "あ、わかりづらいならこのようにお呼びしましょうか？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Oh, or would you prefer if I called you by your other name?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "不明白嗎？還是我換個稱呼？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อ้อ หรืออยากให้ฉันเรียกคุณด้วยอีกชื่อคะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ồ, hay cô thích cháu gọi bằng tên khác hơn?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "啊，如果这个称呼让你有些混淆，不如换一个叫法吧？"
L21_1.m_Talk_SCN = L22_1
