L25_1 = "ALPHA_ACT3_INTERLUDE2@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3900304
L24_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_LAUGH"
L24_1.m_Face = L25_1
L24_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L24_1.m_Pos = "C"
L25_1 = "무슨 소리냐, 지아야. 내 이름은 세실리아 신이라고 했을 텐데."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "何を言っているの、ユイちゃん。私の名前はセシリア・ヒメノよ？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "What nonsense, Jia. I thought I told you that my name is Cecilia Shin."
L24_1.m_Talk_ENG = L25_1
L25_1 = "你在說什麼，我的名字是賽希莉亞！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เหลวไหลแล้วเจีย นึกว่าจะบอกว่าฉันชื่อเซซิเลีย เฉิน ซะอีก"
L24_1.m_Talk_THA = L25_1
L25_1 = "Thật vô lý, Jia. Cô tưởng đã nói với cháu rằng tên cô là Cecilia Shin."
L24_1.m_Talk_VTN = L25_1
L25_1 = "你在说什么，小佳。我是赛西莉亚啊。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Was redest du denn da, Jia? Ich sagte doch, ich heiße Cecilia Shin."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Qu'est-ce que tu racontes, Jia ? Je t'ai dit que je m'appelais Cecilia Shin."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "ALPHA_ACT3_INTERLUDE2@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3900304
L25_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L25_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "그렇군요. 여기 오면 솔직하게 말씀해 주시길 바랐는데……."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そうですか。ここに来たら正直に話してくれると思っていたのに……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I see. I was hoping you’d tell me the truth..."
L25_1.m_Talk_ENG = L26_1
L26_1 = "是嗎？我本來還希望到這裡後，你會自己說實話……"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เข้าใจแล้วค่ะ ฉันก็หวังว่าคุณจะพูดความจริง..."
L25_1.m_Talk_THA = L26_1
L26_1 = "Cháu biết. Cháu đã hy vọng cô sẽ nói cho cháu biết sự thật ..."
L25_1.m_Talk_VTN = L26_1
L26_1 = "是吗。我还以为，在这个时候你会说实话。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ach so. Ich habe gehofft, dass Sie die Wahrheit sagen, wenn wir hier sind ..."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Vraiment ? Moi qui espérais entendre la vérité en venant ici..."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "ALPHA_ACT3_INTERLUDE2@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3900304
L26_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_SERIOUS"
L26_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "숨기려고 하셔도 소용없어요. 고모님은 벌써 세 번이나 실수를 하셨거든요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "隠しても無駄です。叔母様はすでに3回も過ちを犯しましたから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "But there’s no point in hiding it now. You’ve already made three mistakes."
L26_1.m_Talk_ENG = L27_1
L27_1 = "已經瞞不住了，姑姑，因為你犯了三次錯誤。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "แต่ซ่อนไปก็ไม่มีประโยชน์แล้วค่ะ คุณทำพลาดไปสามอย่าง"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nhưng che giấu việc đó không còn ích gì nữa. Cô đã mắc phải ba sai lầm."
L26_1.m_Talk_VTN = L27_1
L27_1 = "继续隐瞒也无济于事，因为姑姑已经失误了三次。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Vertuschen ist zwecklos. Sie haben nämlich schon drei Fehler begangen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Inutile de le cacher. Vous avez déjà fait trois erreurs."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "ALPHA_ACT3_INTERLUDE2@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3900304
L27_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_HATE"
L27_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L27_1.m_Pos = "C"
L27_1.m_Crash = 10
L28_1 = "세 번? 내가 세 번이나 악수를 뒀다고?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "3回？　私が3回も悪手を打ったと？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Three? Are you saying I made three blunders?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "三次？你說我下錯棋三次？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "สามเหรอ? เธอจะบอกว่าฉันเดินหมากผิดไปสามตาเหรอ?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ba sai lầm? Cháu nói ta đã mắc ba sai lầm ư?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "三次？你说我下了三步臭棋？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Drei Fehler? Ich hatte ganze drei schlechte Züge?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Trois erreurs ?"
L27_1.m_Talk_FRA = L28_1
