L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3900304
L29_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L29_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L29_1.m_Pos = "L"
L29_1.m_Crash = 10
L30_1 = "네. 초원 씨, 안경을 잠깐 빌려 주시겠어요?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "はい。ナオさん、ちょっと眼鏡を貸していただけますか？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Yes. Chowon? Could I borrow your glasses for a moment, please?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "對。初源，眼鏡可以借我一下嗎？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ใช่ค่ะ โชวอนคะ ฉันขอยืมแว่นสักครู่ได้มั้ยคะ?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đúng. Chowon? Cho tôi mượn kính một lát được không?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "没错。桃沢梨绘，你能暂时把眼镜借给我吗？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Genau. Chowon, geben Sie mir kurz Ihre Brille?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Oui. Chowon, pourrais-je vous emprunter vos lunettes ?"
L29_1.m_Talk_FRA = L30_1
