L30_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L31_1 = "R_M_I"
L30_1.m_Pos = L31_1
L31_1 = "……알겠습니다. 리더."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "……わかりました、リーダー。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Here you go, Leader."
L30_1.m_Talk_ENG = L31_1
L31_1 = "……沒問題，老大。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เอาไปเลยค่ะท่านผู้นำ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Của cô đây, Thủ Lĩnh."
