L33_1 = "ALPHA_ACT3_INTERLUDE2@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3900304
L32_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "이 알파 비전은 이노베이션의 활동을 촬영, 분석하기 위해 만들어진 데이터 수집기에요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "このアルファビジョンはアルファトリックス・イノベーションの活動を撮影、分析するために作られた\nデータ収集機です。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Alpha Vision is a data collector made to record and analyze the activity at Innovation."
L32_1.m_Talk_ENG = L33_1
L33_1 = "這個阿爾法願景，會將改革的行動錄製下來，加以進行分析後收集資料。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แว่นอัลฟาเป็นอุปกรณ์เก็บข้อมูลที่ทำมาเพื่อบันทึกและวิเคราะห์กิจกรรมต่างๆ ที่อินโนเวชั่นค่ะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Alpha Vision là công cụ thu thập dữ liệu được chế tạo để ghi lại và phân tích hoạt động tại Cải Cách."
L32_1.m_Talk_VTN = L33_1
L33_1 = "这款阿尔法眼镜是为录制并分析阿尔法崔克斯改革的活动而制造的数据收集器。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Diese Alpha Vision ist ein Datensammler für die Aufnahme und Analyse der Aktivitäten bei Innovation."
L32_1.m_Talk_DEU = L33_1
L33_1 = "La Vision alpha a été conçue pour collecter des données permettant de filmer les activités et analyser les activités d'Innovation."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "ALPHA_ACT3_INTERLUDE2@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3900304
L33_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "다시 말해 별도의 조작 없이도 촬영과 녹음이 계속되고 있다는 말이죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "つまり、特別な操作をしなくても撮影と録音が続いているということです。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "In short, it is constantly recording audio and video."
L33_1.m_Talk_ENG = L34_1
L34_1 = "也就是說，不需要額外的操作，它也會持續錄影跟錄音。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "พูดง่ายๆ คือ มันบันทึกเสียงและวิดีโอไว้ตลอด"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nói ngắn gọn là nó liên tục ghi âm và quay video."
L33_1.m_Talk_VTN = L34_1
L34_1 = "换句话说，就算没有额外操作，也会一直进行录像和录音。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "In anderen Worten filmt und nimmt es konstant auf, auch ohne Bedienung."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Autrement dit, elles enregistrent tout ce qui s'y passe, automatiquement."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "ALPHA_ACT3_INTERLUDE2@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3900304
L34_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_HATE"
L34_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L34_1.m_Pos = "C"
L34_1.m_Crash = 10
L35_1 = "그러면……. 나와 대화를 나눌 때도 계속 찍고 있었다고?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ってことは……私と会話する時もずっと撮っていたってこと？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Then... It even has our conversations recorded on there?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "意思是……我和你的對話也有錄下來？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ถ้างั้น... ก็มีแม้แต่บทสนทนาของเราบันทึกไว้สินะ?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Vậy là... Nó thậm chí đã ghi lại cuộc trò chuyện của chúng ta ở đó?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "那……你和我说话的时候，也一直在录像吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Also ... hast du auch unser Gespräch gefilmt?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ça veut dire que.... Ces lunettes ont enregistré toutes nos conversations ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "ALPHA_ACT3_INTERLUDE2@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3900304
L35_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "UNIT_LAUGH"
L35_1.m_Face = L36_1
L35_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "네. 그 때도 이노베이션으로 활동 중이었으니까요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "はい、あの時もアルファトリックス・イノベーションとして活動中でしたので。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Of course. I was on duty as Innovation at the time."
L35_1.m_Talk_ENG = L36_1
L36_1 = "沒錯，因為那也算是改革的行動。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แน่นอนค่ะ ตอนนั้นฉันทำหน้าที่อยู่ที่อินโนเวชั่น"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tất nhiên. Tôi đang làm nhiệm vụ tại Cải Cách lúc đó."
L35_1.m_Talk_VTN = L36_1
L36_1 = "是的。因为当时也是以阿尔法崔克斯改革成员的身份在活动。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Genau. Denn auch damals war ich Teil von Innovation."
L35_1.m_Talk_DEU = L36_1
L36_1 = "C'est exact. Tout ce temps, je travaillais pour le compte d'Innovation."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
