L39_1 = "ALPHA_ACT3_INTERLUDE2@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3900304
L38_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L39_1 = "처음 저희가 만났을 때, 고모님은 범인에 대해 이런 말씀을 하셨어요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "私たちが初めて会った時、叔母様は犯人についてこんなことをおっしゃいました。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "When we first met, you said this to me about the suspect."
L38_1.m_Talk_ENG = L39_1
L39_1 = "我們初次見面時，有關犯人的事，姑姑是這麼說的。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ตอนเราเจอกันครั้งแรก คุณบอกฉันเรื่องผู้ต้องสงสัย"
L38_1.m_Talk_THA = L39_1
L39_1 = "Khi chúng ta gặp nhau lần đầu, cô đã nói điều này với tôi về kẻ tình nghi."
L38_1.m_Talk_VTN = L39_1
L39_1 = "我们第一次遇见时，关于凶手，姑姑曾经说过这样的话。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Als wir uns zum ersten Mal kennengelernt haben, haben Sie das Folgende über den Täter gesagt."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Lorsque nous nous sommes vues pour la premier fois, vous avez dit..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ALPHA_ACT3_INTERLUDE2@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3900304
L39_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "UNIT_DESPAIR"
L39_1.m_Face = L40_1
L39_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L39_1.m_Pos = "C"
L39_1.m_bCharHologramEffect = true
L40_1 = "으음……. 참 고약한 경우가 다 있구나."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "うーん、本当にひどい話だわ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Hmm... You must be going through a lot."
L39_1.m_Talk_ENG = L40_1
L40_1 = "嗯……聽起來確實滿慘的！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อืม... เธอคงเจอมาเยอะทีเดียวสินะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hmm ... Hẳn là cô đã phải trải qua rất nhiều điều."
L39_1.m_Talk_VTN = L40_1
L40_1 = "嗯……果然很可恶。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Hmm ... Wie unglaublich hinterlistig."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Hmm... Quelle terrible affaire."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "ALPHA_ACT3_INTERLUDE2@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3900304
L40_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L40_1.m_Pos = "C"
L40_1.m_bCharHologramEffect = true
L41_1 = "범인이랑 얼굴이 비슷한 것 가지고 살인범으로 몰다니……. 죄다 경솔한 것들뿐이군."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "犯人と顔が似てるからって、それだけで殺人犯扱いだなんて……\n浅はかな奴らばかりなのね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Calling you a murderer because you look similar to the culprit...? That’s the worst excuse I’ve ever heard."
L40_1.m_Talk_ENG = L41_1
L41_1 = "竟然因為長得和犯人很像，就被人當作是殺人犯……似乎太過草率！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "บอกว่าเธอเป็นฆาตกรเพราะเธอดูคล้ายคนร้ายเนี่ยนะ...? เป็นข้อกล่าวหาที่ไร้สาระที่สุดที่เคยได้ยินเลย"
L40_1.m_Talk_THA = L41_1
L41_1 = "Gọi cháu là tên sát nhân vì trông cháu giống với thủ phạm ư...? Đó là lời cái cớ tồi tệ nhất mà cô từng nghe."
L40_1.m_Talk_VTN = L41_1
L41_1 = "仅仅因为脸和凶手长得像，就被当作杀人犯……也太草率了吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Dich einfach als Täter zu beschuldigen, nur weil ihr euch ähnlich seht ... Das sind doch alles Banausen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "T'accuser à tort juste parce que le coupable te ressemblait... C'est malheureux."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
