L42_1.m_Face = "UNIT_SERIOUS"
L42_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L42_1.m_Pos = "L"
L43_1 = "그래서? 이게 뭐 어쨌다는 거니?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "それで？　だからなんだって言うの？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "So? What’s that got to do with this?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "然後呢？有怎麼樣嗎？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แล้วไงล่ะ? มันเกี่ยวอะไรกับเรื่องนี้?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Thế thì sao? Chuyện đó thì liên can gì?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "所以？有什么错吗？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Und? Was ist damit?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Et alors ? Qu'est-ce que ça prouve ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ALPHA_ACT3_INTERLUDE2@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3900304
L43_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L43_1.m_Pos = "L"
L44_1 = "그 시점에는 범인의 정체를 몰랐으니까, 저렇게 말해도 이상하지 않지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "あの時点では犯人の正体がわからなかったから、この会話はおかしくないわ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "We didn't know who the murderer was at the time, so it's not surprising."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我那個時候又不知道犯人是誰，那麼說很正常吧？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ตอนนั้นเรายังไม่รู้นี่ว่าใครเป็นฆาตกร ก็ไม่เห็นจะแปลก"
L43_1.m_Talk_THA = L44_1
L44_1 = "Lúc đó chúng ta không biết kẻ sát nhân là ai, vì vậy không có gì ngạc nhiên cả."
L43_1.m_Talk_VTN = L44_1
L44_1 = "当时因为不知道凶手的真实身份，所以那么说也没什么奇怪的吧。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Damals kannte ich die Identität des Täters nicht, also habe ich das gesagt."
L43_1.m_Talk_DEU = L44_1
L44_1 = "À ce moment-là, personne ne connaissait l'identité du coupable. Quel est le problème ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
