L46_1 = "ALPHA_ACT3_INTERLUDE2@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3900304
L45_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_SERIOUS"
L45_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L45_1.m_Pos = "R"
L46_1 = "네. 맞아요. 범인의 정체를 모르셨죠."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "はい、そうです。叔母様は犯人の正体を知らない状態でした。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Yes, you’re right. We didn’t know who it was."
L45_1.m_Talk_ENG = L46_1
L46_1 = "是的，沒錯，那時候還不知道犯人是誰。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "จริงของคุณค่ะ เราไม่รู้ว่าใคร"
L45_1.m_Talk_THA = L46_1
L46_1 = "Đúng thế. Chúng ta đã không biết đó là ai."
L45_1.m_Talk_VTN = L46_1
L46_1 = "是的，没错。因为不知道凶手的真实身份。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Genau. Sie kannten die Identität des Täters nicht."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Vous avez raison, on ne connaissait pas l'identité du coupable."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "ALPHA_ACT3_INTERLUDE2@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3900304
L46_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L46_1.m_Pos = "R"
L47_1 = "하지만 헤비암즈 사무실에서 고모님은 이렇게 말씀하셨어요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ですが、ヘビーアームズのオフィスで叔母様はこうおっしゃいました。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "However, at the Heavyarms office, this is what you said."
L46_1.m_Talk_ENG = L47_1
L47_1 = "不過在重武裝辦公室時，姑姑這麼說的。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "แต่ตอนอยู่ที่สำนักงานฝ่ายอาวุธหนัก คุณพูดแบบนี้ค่ะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tuy nhiên, tại văn phòng Heavyarms, đây là những gì cô đã nói."
L46_1.m_Talk_VTN = L47_1
L47_1 = "但在重武装军工的办公室，姑姑却这样说。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Aber im Büro von Heavy Arms haben Sie das Folgende gesagt."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Mais dans le bureau de Heavyarms, vous m'avez dit..."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
