L50_1 = "ALPHA_ACT3_INTERLUDE2@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3900304
L49_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L49_1.m_Pos = "C"
L49_1.m_bCharHologramEffect = true
L50_1 = "지아야, 혼란스럽겠지만 내 말 잘 듣거라."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ユイちゃん、混乱しているでしょうけど、私の言うことをよく聞きなさい。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Jia, I know you’re in shock, but listen to me carefully."
L49_1.m_Talk_ENG = L50_1
L50_1 = "小佳，你聽完可能會覺得有點混亂，但你仔細聽我說！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เจีย ฉันรู้นะว่าเธอกำลังช็อก แต่ฟังให้ดีๆ นะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Jia, cô biết cháu đang bị sốc, nhưng hãy nghe kỹ lời cô nói đây."
L49_1.m_Talk_VTN = L50_1
L50_1 = "小佳，虽然你会觉得很混乱，但认真听我说。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Jia, du wirst verwirrt sein, aber hör mir gut zu."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Jia, ça ne va pas être facile à entendre mais écoute-moi bien."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "ALPHA_ACT3_INTERLUDE2@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3900304
