L50_1.m_bCharHologramEffect = true
L51_1 = "이사회에 클론의 존재를 밝혀 봤자 오히려 네 입장만 곤란해질 거다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "理事会にクローンの存在を明かしても、むしろあなたの立場が悪くなるだけだわ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Telling the board about the clone is only going to make things worse for you."
L50_1.m_Talk_ENG = L51_1
L51_1 = "要是被董事會發現有複製人，你可能會更麻煩。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "การบอกพวกกรรมการเรื่องร่างโคลนรังแต่จะทำให้เธอลำบากขึ้นไปอีก"
L50_1.m_Talk_THA = L51_1
L51_1 = "Kể với hội đồng về bản sao chỉ làm mọi thứ với cháu tệ hơn thôi."
L50_1.m_Talk_VTN = L51_1
L51_1 = "如果让理事会知道克隆体的存在，反而会让你的立场变得更艰难。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wenn du den Vorstandsmitgliedern von dem Klon erzählst, bringt dich das nur in Schwierigkeiten."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Si le Conseil découvre l'existence du clone, tu risques de te retrouver dans une position délicate."
L50_1.m_Talk_FRA = L51_1
