L2_1.m_Face = "UNIT_IDLE"
L2_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L2_1.m_Pos = "C"
L3_1 = "어떻게 헤비암즈에 막 도착하신 상황에서 실행범이 클론인 줄 알아차리셨을까요?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ヘビーアームズに到着したばかりの状況で、どうして実行犯が\nクローンだと気づいたのでしょう？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "How did you know that the killer was a clone as soon as you arrived at Heavyarms?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "那時才剛抵達重武裝而已，怎麼可能馬上就知道犯人是複製人？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คุณรู้ได้ยังไงคะว่าฆาตกรเป็นร่างโคลน ทั้งที่ก็เพิ่งไปถึงที่ฝ่ายอาวุธหนัก?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Sao cô biết tên sát nhân là một bản sao ngay khi cô vừa đến Heavyarms cơ chứ?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "那你是如何在刚刚抵达重武装军工的情况下，就判断出行凶者是克隆体呢？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Woher wussten Sie, dass die Tatausführende ein Klon war, obwohl Sie gerade erst in Heavy Arms angekommen waren?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Comment avez-vous su qu'il y avait un clone dès notre arrivée à Heavyarms ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "ALPHA_ACT3_INTERLUDE2@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3900304
L3_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SERIOUS"
L3_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "제가 그 실행범이 클론이라고 들은 건 재혁 오라버니로부터였는데 말이에요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "私にその実行犯がクローンだと教えてくれたのはタツヤお兄様だったのに。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I only heard that it was a clone because Jaehyuk told me so."
L3_1.m_Talk_ENG = L4_1
L4_1 = "是大哥告訴我，我才知道原來行兇的人是複製人的。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ที่ฉันรู้ว่าเป็นร่างโคลนก็เพราะแจฮย็อกบอกแบบนั้นค่ะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cháu chỉ nghe nói rằng đó là một bản sao vì anh Jaehyuk đã nói thế."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我知道行凶者是克隆体，还是宰赫哥哥告诉我的。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ich wusste nur, dass die Tatausführende ein Klon ist, weil Jaehyuk mir das erzählt hat."
L3_1.m_Talk_DEU = L4_1
L4_1 = "L'identité de l'exécutrice, je l'ai apprise par Jaehyuk."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
