L6_1 = "ALPHA_ACT3_INTERLUDE2@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3900304
L5_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_SERIOUS"
L5_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "고모님이 카운터라면 그와 관련된 능력을 가지고 계실지도 모르겠지만……."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "叔母様がカウンターなら、それを知ることができる能力を\n持っていらっしゃるかもしれませんが……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "If you were a Counter, it would’ve made more sense, but..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "如果因為姑姑是制裁者，所以有類似能力，那還說得過去……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ถ้าคุณเป็นเคาน์เตอร์ มันก็คงพอฟังขึ้น แต่ว่า..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Nếu cô là Counter, điều đó sẽ hợp lý hơn, nhưng..."
L5_1.m_Talk_VTN = L6_1
L6_1 = "如果姑姑是制裁者，说不定是因为有某种相关的能力……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Falls Sie ein Counter wären, könnten Sie vielleicht eine diesbezügliche Fähigkeit haben ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "À moins que vous ne soyez aussi un Counter et que vous possédiez des compétences pour ce genre de situation... ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "ALPHA_ACT3_INTERLUDE2@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3900304
L6_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "본인은 저에게 줄곧 카운터가 아니라고 주장하셨잖아요?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "これまで何度も私にカウンターではないと主張していたでしょう？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You’ve been stating that you’re not, haven’t you?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "但你不是一直堅持自己不是制裁者嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "คุณบอกว่าคุณไม่ได้เป็นนี่คะ จริงมั้ย?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô đã nói rằng mình không phải, đúng chứ?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "但你不是一直声称，自己，或者说是塞西莉亚，不是制裁者吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Aber Sie haben zu mir ständig behauptet, dass Sie kein Counter seien."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais vous m'avez bien dit que vous n'étiez pas un Counter, non ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "ALPHA_ACT3_INTERLUDE2@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3900304
L7_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "그렇다면 답은 하나. 고모님은 처음부터 실행범이 클론인 줄 알고 계셨던 거예요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "それなら答えは一つです。\n叔母様は最初から実行犯がクローンだと知っていたんです。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Then there’s only one conclusion. You knew who the killer was from the start, Auntie."
L7_1.m_Talk_ENG = L8_1
L8_1 = "那麼答案就只有一個，也就是姑姑你從頭到尾都知道行兇的是複製人。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ดังนั้น ข้อสรุปก็มีเพียงหนึ่งเดียวค่ะ คุณรู้แต่แรกว่าใครเป็นฆาตกรนะคะอา"
L7_1.m_Talk_THA = L8_1
L8_1 = "Vậy thì chỉ có một kết luận. Ngay từ đầu cô đã biết ai là tên sát nhân."
L7_1.m_Talk_VTN = L8_1
L8_1 = "那么答案只有一个。姑姑从一开始就知道行凶者是克隆体。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Dann gibt es nur eine mögliche Antwort: Sie wussten von Anfang an, dass die Tatausführende ein Klon ist."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Dans ce cas, il n'y a qu'une seule possibilité. Vous saviez dès le départ que l'exécutrice était un clone."
L7_1.m_Talk_FRA = L8_1
