L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3900304
L10_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_SURPRISE"
L10_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L10_1.m_Pos = "L"
L10_1.m_Crash = 10
L11_1 = "잠깐, 그럼……."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ちょっと待って、つまり……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Hold on. Then..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "等等，所以說……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เดี๋ยวนะคะ ถ้างั้น..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Chờ đã. Vậy..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "等等，那么……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Moment, dann ..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Attendez, mais alors..."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "ALPHA_ACT3_INTERLUDE2@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3900304
L11_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_SERIOUS"
L11_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L11_1.m_Pos = "R"
L12_1 = "맞아. 저 꼬마가 이번 사건에서 최소 공범 이상이라는 뜻이야."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "そうです。あのチビが今回の事件において、少なくとも共犯以上という意味になります。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Yeah. That kid’s got something to do with everything that happened."
L11_1.m_Talk_ENG = L12_1
L12_1 = "沒錯，那個小鬼一定有參與這次的事件。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ใช่ ยัยเด็กนั่นมีเอี่ยวกับเรื่องที่เกิดขึ้น"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đúng thế. Con nhóc đó hẳn liên quan đến mọi thứ đã xảy ra."
L11_1.m_Talk_VTN = L12_1
L12_1 = "没错。这么说的话，那个小不点在这次的事件中，至少是共犯以上的存在。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Genau. Dieser Knirps ist zumindest eine Mittäterin in diesem Fall."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Oui, cette gamine était une complice de l'affaire. Une complice au moins..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
