L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3900304
L13_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_IDLE"
L13_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L13_1.m_Pos = "C"
L13_1.m_Crash = 10
L14_1 = "흐음, 듣고 나니 확실히 이상하지만……."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ふうん。そう言われたら確かに怪しいと思われても仕方ないけど……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Hmm... Now that you mention it, it does sound weird..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "嗯嗯，聽你分析完，確實是有可疑之處……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "อืมม... จะว่าไป มันก็ฟังดูแปลกนะ..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Hmm... Bây giờ cháu nói ta mới thấy lạ..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "哼嗯，这么听起来确实有些奇怪……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Hmm, du hast recht, das ist merkwürdig ..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Hmm. Bon dit comme ça, ça peut paraitre étrange mais..."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "ALPHA_ACT3_INTERLUDE2@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3900304
L14_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L14_1.m_Pos = "C"
L15_1 = "말실수 하나로 트집 잡는 건 너무하지 않니?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "たった失言一つで言いがかりをつけるのはひどいんじゃない？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "But don’t you think it’s a stretch accusing me over a tiny mistake?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "但我不過就是說錯一句話，有需要這樣找我麻煩嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "แต่มันไม่รวบตึงไปหน่อยเหรอ ที่จะมากล่าวหาฉันด้วยข้อผิดพลาดเล็กๆ น้อยๆ น่ะ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Nhưng cháu không nghĩ rằng đó là sai sót nhỏ do quá căng thẳng thôi sao?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "但因为说错一次话，就被当做是坏人，也太过分了吧？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Aber ist es nicht übertrieben, mich aufgrund eines Versprechers zu beschuldigen?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Inutile d'en faire toute une histoire pour quelques paroles maladroites, non ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "ALPHA_ACT3_INTERLUDE2@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3900304
L15_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_IDLE"
L15_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "네. 그렇지만 고모님의 두 번째 실수는 밸런스 브레이커를 너무 많이 생산하신 거예요."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "それだけではありません。叔母様の2つ目のミスは、バランスブレイカーを生産しすぎたことです。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "True. But your second mistake was producing too many Balance Breakers."
L15_1.m_Talk_ENG = L16_1
L16_1 = "當然不只如此，姑姑犯的第二個錯，就是大量生產平衡破壞者。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ก็จริงค่ะ แต่ความผิดพลาดเรื่องที่สองก็คือเรื่องการผลิตผู้ทำลายสมดุลจำนวนมากเกินไป"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đúng. Nhưng sai lầm thứ hai của cô là sản xuất quá nhiều Balance Breakers."
L15_1.m_Talk_VTN = L16_1
L16_1 = "嗯，但姑姑的第二个失误，就是生产了太多平衡破坏者。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ja. Aber Ihr zweiter Fehler war, dass Sie zu viele Balancebrecher produziert haben."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ce qui nous amène à votre deuxième erreur. Vous avez fabriqué trop de Briseurs d'équilibre."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
