L18_1 = "ALPHA_ACT3_INTERLUDE2@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3900304
L17_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_SERIOUS"
L17_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "밸런스 브레이커는 가격 때문에 많이 생산하기 어려운 무기니까요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "バランスブレイカーはその価格のせいで、大量生産には向いていない武器です。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Balance Breaker is a difficult weapon to produce due to its high cost."
L17_1.m_Talk_ENG = L18_1
L18_1 = "平衡破壞者的製造成本高昂，因此無法大量生產。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ผู้ทำลายสมดุลเป็นอาวุธที่ผลิตยากเพราะต้นทุนสูงนะคะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Balance Breaker là một vũ khí khó sản xuất do giá thành cao."
L17_1.m_Talk_VTN = L18_1
L18_1 = "平衡破坏者因为其价格原因，是很难生产的武器。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Balancebrecher sind schwierig in Masse zu produzierende Waffen, weil sie teuer sind."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ces armes coûtent cher, il n'est donc pas donné à tout le monde de les fabriquer en masse."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "ALPHA_ACT3_INTERLUDE2@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3900304
L18_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = "그런 고가의 무기를 여러 정 생산할 정도라면, 그걸 쓸 클론들도 그만큼 있다는 뜻이겠죠?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そんな高価な武器を複数生産するということは、\nそれを使うクローンもそれだけいるということでしょう。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "But if you were to have produced that many of them, it can only mean that you have created as many clones."
L18_1.m_Talk_ENG = L19_1
L19_1 = "既然製造出那麼多高價的武器，那當然也就要有足夠數量的複製人吧？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แต่ถ้าคุณจะผลิตมากขนาดนั้น ก็หมายความว่าคุณผลิตร่างโคลนขึ้นมาหลายตัว"
L18_1.m_Talk_THA = L19_1
L19_1 = "Nhưng nếu cô đã tạo ra số lượng lớn vũ khí đó, điều đó chỉ có thể là cô đã tạo ra quá nhiều bản sao."
L18_1.m_Talk_VTN = L19_1
L19_1 = "但是如果生产了很多个那么高价的武器，就说明有很多个可以使用那些武器的克隆体吧？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Wenn man trotzdem viele von diesen teuren Waffen produziert, muss das heißen, dass man genügend Klone für deren Einsatz besitzt."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Si vous avez créé autant de Briseurs d'équilibre, c'est qu'il existe autant de clones, non ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
