L19_1.m_Face = "UNIT_PRIDE"
L19_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L19_1.m_Pos = "C"
L19_1.m_Crash = 10
L20_1 = "알파트릭스 그룹에서도 그런 설비를 갖춘 곳은 한 곳뿐이에요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "アルファトリックスグループの中でも、そんな設備を揃えているところは\n一か所しかありません。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "And there’s only one place in Alphatrix capable of making that many."
L19_1.m_Talk_ENG = L20_1
L20_1 = "而在阿爾法崔克斯集團中，只有一個地方有這種設備。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "และก็มีที่เดียวในอัลฟาทริกซ์ที่ทำได้เยอะขนาดนั้น"
L19_1.m_Talk_THA = L20_1
L20_1 = "Và chỉ có một nơi duy nhất ở Alphatrix có khả năng tạo ra nhiều thứ như vậy."
L19_1.m_Talk_VTN = L20_1
L20_1 = "在阿尔法崔克斯集团，具备那种生物设备的地方只有一处。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Es gibt nur einen Ort in Alphatrix, der eine solche Ausstattung hat."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Et il n'y a qu'un endroit disposant ce genre d'installation dans le groupe Alphatrix."
L19_1.m_Talk_FRA = L20_1
