L21_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L22_1 = "바로 고모님의 <color=#ffd34c>알파트릭스 바이오닉스</color>죠."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "叔母様の<color=#ffd34c>アルファトリックス・バイオニクス</color>です。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "That would be your <color=#ffd34c>Alphatrix Bionics</color>."
L21_1.m_Talk_ENG = L22_1
L22_1 = "就是姑姑的<color=#ffd34c>阿爾法崔克斯仿生</color>。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ซึ่งก็คือ<color=#ffd34c>ฝ่ายไบโอนิกส์ของอัลฟาทริกซ์</color>ที่คุณดูแลค่ะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Đó sẽ là <color=#ffd34c>Alphatrix Bionics</color>."
L21_1.m_Talk_VTN = L22_1
L22_1 = "就是姑姑负责的<color=#ffd34c>阿尔法崔克斯生物科技</color>。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Und zwar <color=#ffd34c>Alphatrix Bionix</color> von Ihnen, Tante."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Votre société. <color=#ffd34c>Alphatrix Bionix</color>."
L21_1.m_Talk_FRA = L22_1
