L24_1 = "ALPHA_ACT3_INTERLUDE2@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3900304
L23_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L23_1.m_Pos = "C"
L24_1 = "어차피 정황 증거에 불과한데? 바이오닉스 대표부터 찾는 게 상식 아닐까?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そんなの状況証拠にすぎないわよ？\nまずは私じゃなくて、バイオニクスの代表を探すのが常識じゃない？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Doesn’t seem like substantial evidence to me? Wouldn’t finding out who the CEO of Bionics be the priority?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "聽起來只是間接證據而已？先找上仿生代表是正常的吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฉันว่าหลักฐานยังไม่มากพอรึเปล่านะแบบนั้น? ต้องหาก่อนรึเปล่านะว่าใครเป็น CEO ของฝ่ายไบโอนิกส์?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Đó dường như không phải là bằng chứng đáng kể? Chẳng phải việc tìm ra ai là CEO Bionics là ưu tiên sao?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "这些都是间接的证据吧？通常不是应该先去找生物科技的代表吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Das sind doch nur Indizien. Solltest du nicht zuerst den Vorsitzenden von Bionix finden?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Tout ce que j'entends, ce sont des conjectures. Tu devrais d'abord aller voir le président de Bionix."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "ALPHA_ACT3_INTERLUDE2@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3900304
L24_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_LAUGH"
L24_1.m_Face = L25_1
L24_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L24_1.m_Pos = "C"
L24_1.m_Crash = 10
L25_1 = "다행히 그 부분에 대해선 저보다 먼저 짚어 주신 분이 계시거든요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "幸い、それについて私より先に気づいた方がいました。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Luckily, someone else had already done that for us."
L24_1.m_Talk_ENG = L25_1
L25_1 = "幸好有人比我早發現這一點。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "โชคดีที่มีคนทำเรื่องนั้นให้เราแล้วค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "May mắn là một người khác đã làm điều đó cho chúng tôi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "关于这部分，多亏有人比我先走了一步。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Zum Glück gab mir jemand diesbezüglich den richtigen Hinweis."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Heureusement, quelqu'un d'autre a été plus rapide que moi."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
