L27_1 = "경위님께서 세실리아란 분을 조사해 주셨어요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "マエカワ警部補がセシリアという人物について調べてくれました。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You see, Lieutenant Kang did a background check on the name Cecilia."
L26_1.m_Talk_ENG = L27_1
L27_1 = "警衛已經調查過賽希莉亞這個人，"
L26_1.m_Talk_TWN = L27_1
L27_1 = "นี่ค่ะ ผู้หมวดคังตรวจสอบภูมิหลังของชื่อเซซิเลียมาแล้ว"
L26_1.m_Talk_THA = L27_1
L27_1 = "Trung Úy Kang đã kiểm tra lý lịch về cái tên Cecilia."
L26_1.m_Talk_VTN = L27_1
L27_1 = "樱井爱理警卫调查了关于赛西莉亚的情况。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Die Leutnantin hat für mich eine Person namens Cecilia untersucht."
L26_1.m_Talk_DEU = L27_1
L27_1 = "La lieutenante a mené une enquête sur vous."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "ALPHA_ACT3_INTERLUDE2@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3900304
L27_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L28_1 = "어머니 집안의 특허권을 빼앗긴 뒤 버려진 채 난민지구를 전전하다가……."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "母方の家の特許権を奪われた後、\n捨てられた身で難民地区を転々としていましたが……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "She was abandoned and wandered around the refugee district after her mother's family lost their patent rights..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "媽媽的專利被奪走後，她就流落到難民區……"
L27_1.m_Talk_TWN = L28_1
L28_1 = "หลังจากพ่อแม่เสียสิทธิบัตรไป เธอก็ถูกทิ้งให้เร่ร่อนไปในเขตผู้ลี้ภัย..."
L27_1.m_Talk_THA = L28_1
L28_1 = "Cô bé bị bỏ rơi và lang thang khắp các khu tị nạn sau khi gia đình mẹ cô ấy mất quyền sáng chế..."
L27_1.m_Talk_VTN = L28_1
L28_1 = "在她母亲被家族夺走专利权后，她们就被遗弃在难民区，一直在那边生活……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Sie wurde verlassen, nachdem ihr ein Patent mütterlicherseits gestohlen wurde, und sie lebte im Flüchtlingsviertel ..."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Votre mère a perdu tous les brevets de la famille, puis elle a été envoyée dans le district des réfugiés..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "ALPHA_ACT3_INTERLUDE2@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3900304
L28_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L29_1 = "얼마 전 소식이 두절되었다고 해요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "しばらく前に消息が途絶えたそうです。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Then disappeared recently."
L28_1.m_Talk_ENG = L29_1
L29_1 = "不久前彷彿人間蒸發，都沒有她的消息。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แล้วไม่กี่วันหลังจากนั้นก็หายตัวไป"
L28_1.m_Talk_THA = L29_1
L29_1 = "Sau đó gần đây cô bé đã biến mất vài ngày."
L28_1.m_Talk_VTN = L29_1
L29_1 = "直到不久前失去了消息。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "bis sie vor einiger Zeit jeglichen Kontakt abbrach."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Mais ces derniers temps, elle est injoignable."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
