L31_1 = "UNIT_LAUGH"
L30_1.m_Face = L31_1
L30_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "역시 경찰 분들은 대단하세요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "さすが警察の方はすごいですね。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "The police here are outstanding."
L30_1.m_Talk_ENG = L31_1
L31_1 = "警察很厲害吧！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ตำรวจที่นี่เก่งมากนะคะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cảnh sát ở đây rất xuất sắc."
L30_1.m_Talk_VTN = L31_1
L31_1 = "警察们还是很厉害的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Die Polizei ist wirklich beeindruckend."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Hé oui, la police fait bien son travail."
L30_1.m_Talk_FRA = L31_1
