L32_1 = "ALPHA_ACT3_INTERLUDE2@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3900304
L31_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "잠깐 마주쳤을 뿐인데 이상한 점을 바로 알아차리셨잖아요? 그렇죠?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ほんの少し会っただけなのに、怪しい点にすぐ気づいたんですよ？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "It was only a brief encounter, but they noticed something odd right away."
L31_1.m_Talk_ENG = L32_1
L32_1 = "是不是？只是稍微見過面而已，就可以立刻察覺到不對勁的地方。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ทั้งที่เจอกันแค่สั้นๆ แต่ก็สังเกตเรื่องผิดปกติได้ทันที"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chỉ là một cuộc gặp gỡ ngắn ngủi, nhưng ngay lập tức họ đã nhận ra điều bất thường."
L31_1.m_Talk_VTN = L32_1
L32_1 = "仅仅短暂接触了一会儿，马上就发现了你奇怪的地方。对吧？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Sie hat sofort gemerkt, dass etwas faul ist, trotz dieser kurzen Begegnung. Nicht wahr?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ces policières vous ont simplement croisée mais elles vous ont tout de suite suspectée."
L31_1.m_Talk_FRA = L32_1
