L34_1.m_Pos = "L"
L34_1.m_Crash = 10
L35_1 = "그건……. 그 경찰이 별종 같군."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "それは……その警察が特別なだけだと思うが。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "That’s because... that cop is a weirdo."
L34_1.m_Talk_ENG = L35_1
L35_1 = "呃……那位警察好像是特例。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "นั่นก็เพราะ... ตำรวจคนนั้นนางพิลึกไงล่ะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đó là bởi vì... cảnh sát đó là một kẻ lập dị."
L34_1.m_Talk_VTN = L35_1
L35_1 = "那个……因为那个警察姐姐是个怪咖。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ich glaube ... man kann sie nicht gewöhnlich nennen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Les policières de l'autre fois ? C'étaient de sacrés numéros."
L34_1.m_Talk_FRA = L35_1
