L38_1 = "ALPHA_ACT3_INTERLUDE2@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900304
L37_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_SURPRISE"
L37_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L37_1.m_Pos = "L"
L37_1.m_Crash = 10
L38_1 = "그러면 뭐야? 저기 있는 쟤는?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "じゃあ誰なの？　そこにいる子は？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Hold on. Then who’s she?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "所以呢？她到底是誰？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เดี๋ยวนะคะ แล้วเธอเป็นใคร?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chờ đã. Vậy cô ta là ai?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "那么她是怎么回事？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Und was ist dann mit der da?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Mais alors c'est elle qui... Mais ce visage, comment... ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ALPHA_ACT3_INTERLUDE2@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3900304
L38_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SERIOUS"
L38_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L38_1.m_Pos = "R"
L39_1 = "불법 유통된 아티팩트……. 내지는 실제로 외과적인 성형 수술을 동원했을 수도 있어."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "違法に入手したアーティファクト……\nあるいは、実際に整形手術を行ったかもしれない。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "An illegally smuggled Artifact... Or she could’ve gotten surgery to change her appearance."
L38_1.m_Talk_ENG = L39_1
L39_1 = "可能是非法流通的人造物……甚至可能真的有動整型手術。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อาร์ติแฟ็กต์ที่ลักลอบค้ากันอย่างผิดกฎหมาย... หรืออาจศัลยกรรมเปลี่ยนหน้ามา"
L38_1.m_Talk_THA = L39_1
L39_1 = "Là nhờ một Thần Khí được lưu thông bất hợp pháp... Hoặc cô ta đã phẫu thuật thẩm mỹ để thay đổi ngoại hình."
L38_1.m_Talk_VTN = L39_1
L39_1 = "非法流通的人造神器……或者是进行了外科手术。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Sie ist entweder ein illegal vertriebenes Artefakt ... Oder hat sich tatsächlich eine Gesichts-OP unterzogen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Elle aura sûrement utilisé un artefact illégal... ou procédé à une opération de chirurgie esthétique."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ALPHA_ACT3_INTERLUDE2@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3900304
L39_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L39_1.m_Pos = "R"
L39_1.m_Crash = 10
L40_1 = "제식 장비의 생체신호를 속일 정도의 생명공학 기술이라면 불가능한 일도 아니야."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "制式装備の生体信号を欺けるほどの生命工学技術なら、\n不可能なことでもないでしょう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "If she has the technology to spoof the biometric signals, it’s not entirely impossible."
L39_1.m_Talk_ENG = L40_1
L40_1 = "要騙過制式裝備的身分信號，只要利用生物技術應該不是難事。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ถ้าเธอมีเทคโนโลยีที่รบกวนสัญญาณชีวมาตรได้ ก็ไม่ใช่ว่าจะเป็นไปไม่ได้เสียทีเดียว"
L39_1.m_Talk_THA = L40_1
L40_1 = "Nếu cô ấy có công nghệ giả mạo các tín hiệu sinh trắc học, việc đó hẳn không phải là không có khả năng."
L39_1.m_Talk_VTN = L40_1
L40_1 = "如果具备相应生物工程技术来欺骗读取生物信号的制式装备，这也不是不可能做到的事情。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Unmöglich wäre das nicht, wenn schon eine Biotechnologie möglich ist, die die Körpersignale einer Standard-Ausrüstung täuscht."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Avec les techniques biotechonologiques, on peut tromper le signal biométrique d'un équipement."
L39_1.m_Talk_FRA = L40_1
