L43_1 = "이 정도까지 몰리니 세 번째도 궁금해지는걸."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ここまで追い詰められたら、3つ目も気になるわね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Since you’ve got me all cornered, I wonder what the third blunder is."
L42_1.m_Talk_ENG = L43_1
L43_1 = "可以把我逼到這種程度，讓我更好奇第三個是什麼呢！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ต้อนกันจนมุมขนาดนี้ ฉันสงสัยแล้วสิว่าข้อผิดพลาดที่สามคืออะไร"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cháu đã dồn ép ta hết mức, vậy sai lầm thứ ba là gì."
L42_1.m_Talk_VTN = L43_1
L43_1 = "事已至此，我有些好奇第三个失误是什么了。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Unter so viel Druck werde ich neugierig auf das Dritte."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Je ne m'attendais pas à ça. Maintenant, j'ai hâte d'entendre quelle a été ma dernière erreur."
L42_1.m_Talk_FRA = L43_1
