L44_1 = "마지막은 뭐니, 지아야?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "最後は何かしら、ユイちゃん。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "So, what’s my last blunder, Jia?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "你說吧，小佳！最後一個是什麼？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เอ้า ข้อผิดพลาดสุดท้ายของฉันคืออะไรล่ะเจีย?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Vậy, sai lầm cuối cùng của ta là gì, Jia?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "最后一步臭棋是什么呢，小佳？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Was ist der letzte Fehler, Jia?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Dis-moi tout, Jia."
L43_1.m_Talk_FRA = L44_1
