L45_1.m_fTalkTime = 0.03
L46_1 = "あ、3つ目はこれからすると思います。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Your third mistake is going to happen soon."
L45_1.m_Talk_ENG = L46_1
L46_1 = "喔，第三個錯誤你正要犯。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ข้อผิดพลาดที่สามของคุณกำลังจะเกิดขึ้นค่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Sai lầm thứ ba của cô sắp xảy ra."
L45_1.m_Talk_VTN = L46_1
L46_1 = "啊，第三个的话，马上就要发生了。"
L45_1.m_Talk_SCN = L46_1
