L47_1.m_Pos = "C"
L48_1 = "왜냐하면…… <color=#ffd34c>고모님은 기물을 소중하게 안 다루시니까요.</color>"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "なぜなら……<color=#ffd34c>叔母様は一駒一駒を大切に扱わないからです。</color>"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Because... <color=#ffd34c>you don’t treat your pieces with respect, Auntie.</color>"
L47_1.m_Talk_ENG = L48_1
L48_1 = "因為……<color=#ffd34c>姑姑在下棋時沒有步步為營</color>。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เพราะว่า... <color=#ffd34c>น้าไม่เคารพตัวหมากของตัวเองไงคะ</color>"
L47_1.m_Talk_THA = L48_1
L48_1 = "Bởi vì... <color=#ffd34c>Cô không đối xử tôn trọng với những quân cờ của mình.</color>"
L47_1.m_Talk_VTN = L48_1
L48_1 = "因为……<color=#ffd34c>姑姑对每个棋子都不是很在意。</color>"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Denn ... <color=#ffd34c>Sie schätzen Ihre Schachfiguren nicht, Tante.</color>"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous ne vous rappelez pas ? <color=#ffd34c>Vous manquez toujours de prudence en avançant vos pions sur l'échiquier...</color>."
L47_1.m_Talk_FRA = L48_1
