L48_1.m_Talk_TWN = L49_1
L49_1 = "ทัศนคติแบบนั้นจะย้อนกลับมาเข้าตัวแน่นอนค่ะ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Thái độ đó chắc chắn sẽ phản lại cô."
L48_1.m_Talk_VTN = L49_1
L49_1 = "这种下棋风格，一定会拖姑姑的后腿。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Diese Spielart wird Ihnen teuer zu stehen kommen."
