L4_1.m_Pos = "L"
L5_1 = "십 몇 년도 더 된 대국을 아직도 기억해 주다니 이거 영광이구나, 지아야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "十数年前の対局を未だに覚えてくれてるなんて嬉しいわ、ユイちゃん。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I’m surprised you still remember our little game back from all those years, Jia!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "這盤棋下了十幾年，你竟然還記得，我真是榮幸呢，小佳。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แปลกใจจริงๆ ที่ผ่านมาตั้งหลายปีแล้วเธอยังจำหมากรุกที่เราเล่นกันได้นะเจีย!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Ta ngạc nhiên vì mi vẫn còn nhớ trò chơi nho nhỏ hồi đó đấy, Jia!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "竟然还记得十几年前的那盘对局，我真是倍感荣幸呢，小佳。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Welch Ehre, dass du dich an eine mehr als zehn Jahre alte Partie erinnerst, Jia."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Tu te souviens encore de cette partie d'échecs ? C'est un honneur, Jia."
L4_1.m_Talk_FRA = L5_1
