L6_1 = "나름대로 블러핑에 공을 기울였는데 네게는 소용없었던 모양이네."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "それなりにブラフィングに力を入れたつもりだけど、あんたには無駄だったようね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I’ve put in a lot of effort into my bluffing, but it seems that it’s no use against you."
L5_1.m_Talk_ENG = L6_1
L6_1 = "虧我還演得這麼認真，看來還是沒能騙過你。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันพยายามบลัฟเธอแทบตาย แต่ดูเหมือนจะทำอะไรเธอไม่ได้เลย"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ta đã nỗ lực rất nhiều cho trò lừa bịp của mình, nhưng có vẻ như điều đó là vô ích đối với mi."
L5_1.m_Talk_VTN = L6_1
L6_1 = "我已经尽力伪装了，但好像对你没起作用。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich habe mein Bestes getan, um zu bluffen, aber gegen dich war es zwecklos."
L5_1.m_Talk_DEU = L6_1
L6_1 = "J'ai bien essayé de bluffer, mais on dirait que ça n'a pas marché."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "ALPHA_ACT3_INTERLUDE2@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3900304
L6_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_SERIOUS"
L6_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "얼굴과 신분까지 속여 가면서……. 대체 왜 이런 짓을 저지르신 거죠?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "顔と身元まで偽って……いったいなぜこんなことをしたのですか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Why are you doing this while going to the extent of concealing your identity and even your face?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "你用別人的臉和身分來欺騙我們……你到底為什麼要這麼做？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ทำไมต้องทำถึงขั้นปกปิดตัวตนหรือกระทั่งใบหน้าตัวเองคะ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô giả mạo danh tính và cả khuôn mặt của mình đến mức này để làm gì?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "不惜伪造长相和身份……你到底为什么要做这种事？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Warum tun sie das ...? Sogar mit falschem Gesicht und falscher Identität?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Vous avez changé de visage, changé d'identité... Pourquoi avoir fait tout ça ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
