L11_1.m_Face = "UNIT_SERIOUS"
L11_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L11_1.m_Pos = "R"
L12_1 = "고모님의 목표는 저 하나 아닌가요?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "叔母様のターゲットは私一人じゃないですか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Isn’t it me who you want?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "姑姑的目標不是我嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "คุณต้องการตัวฉันไม่ใช่เหรอ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Chẳng phải cô muốn nhắm đến cháu sao?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "姑姑的目标难道不是我一个人吗？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich bin doch Ihr einziges Ziel, oder, Tante?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Vous vouliez juste m'éliminer, n'est-ce pas ?"
L11_1.m_Talk_FRA = L12_1
