L13_1 = "ALPHA_ACT3_INTERLUDE2@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3900304
L12_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L12_1.m_Pos = "R"
L12_1.m_Crash = 10
L13_1 = "많은 분들이 이번 일로 피해를 입었어요. 숙부님처럼 목숨을 잃은 분들도 계시고요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "たくさんの方々が今回の件で被害を受けました。\n叔父様のように亡くなられた方もいらっしゃいます。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "But instead, you caused pain and suffering to others. Some have even lost their lives like my uncle."
L12_1.m_Talk_ENG = L13_1
L13_1 = "可是卻有這麼多人因為這次的事件受傷，叔叔甚至還因此喪命！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แต่คุณกลับไปทำให้คนอื่นต้องเจ็บปวดทรมานแทน บางคนถึงกับต้องเสียชีวิตอย่างลุงของฉัน"
L12_1.m_Talk_THA = L13_1
L13_1 = "Thế mà cô lại gây đau đớn, khổ sở cho những người khác. Thậm chí có những người đã mất mạng, như bác trai của cháu vậy."
L12_1.m_Talk_VTN = L13_1
L13_1 = "有很多人因为这次的事件受到了伤害。甚至还有人像叔父那样失去了生命。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Viele kamen durch diese Angelegenheit zu Schaden. Manche, wie mein Onkel, haben ihr Leben verloren."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Beaucoup de gens ont subi des préjudices dans cette histoire. Il y en a même qui ont perdu la vie comme mon oncle."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
