L17_1 = "정말 몰라서 묻니, 그걸?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "本当にわからなくて聞いてるの？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Asking because you don’t know?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "是真的不知道才問的嗎？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ถามเพราะไม่รู้จริงๆ เหรอ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Hỏi vì mi không biết không?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "真的是因为不知道才问吗？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Fragst du das wirklich, weil du ahnungslos bist?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Tu ne sais vraiment pas pourquoi ?"
L16_1.m_Talk_FRA = L17_1
