L20_1 = "ALPHA_ACT3_INTERLUDE2@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3900304
L19_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SERIOUS"
L19_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L19_1.m_Pos = "L"
L19_1.m_Crash = 10
L20_1 = "내 정체는 잘만 알아차리면서 정작 이유는 모르겠다고? 관심이 없는 거겠지!!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "私の正体は突き止めたくせに、肝心の理由がわからないって？\n興味ないだけでしょ！！"
L19_1.m_Talk_JPN = L20_1
L20_1 = "You figured out it was me, but not my motives? More like you didn’t even bother!!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "你已經知道我的身分，卻還不知道我真正的理由？你是不知道還是不想知道！！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เธอคิดจนออกว่าเป็นฝีมือฉันแต่ไม่รู้แรงจูงใจเหรอ? ท่าจะไม่สนเลยซะมากกว่า!!"
L19_1.m_Talk_THA = L20_1
L20_1 = "Mi biết đó là ta, nhưng lại không đoán ra động cơ của ta ư? Chẳng qua là mi không để tâm!!"
L19_1.m_Talk_VTN = L20_1
L20_1 = "你能轻易发现我的真实身份，却不知道我这么做的原因？是你对此毫不关心才对吧?"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Du erkennst meine Identität, aber nicht meine Beweggründe? Dir ist es halt egal!!!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Tu as découvert qui j'étais et tu me demandes pourquoi ? Décidément, tu es insensible jusqu'au bout..."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
