L23_1 = 0.15
L21_1[1] = L22_1
L21_1[2] = L23_1
L20_1.m_Bounce = L21_1
L21_1 = "뻔하잖아! 네가 먼저 내 모든 걸 빼앗아 갔으니까!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "決まってるじゃない！　あんたが先に私のすべてを奪っていったからよ！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Isn’t it obvious? You took everything away from me!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "這不是很明顯嗎！因為你奪走我的一切！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ก็เห็นอยู่ทนโท่มั้ย? เธอเอาทุกอย่างไปจากฉันไง!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Không phải quá rõ ràng sao? Mày đã lấy hết mọi thứ của tao!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "难道不明显吗？因为你抢走了我的一切！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ist doch klar! Du hast mir mein Alles weggenommen!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "C'est évident non ? C'est toi qui m'as tout pris !"
L20_1.m_Talk_FRA = L21_1
