L24_1 = "아, 그거야. 바로 그 표정……."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ああ、それよ。まさしくその顔……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Yeah, that’s it. It’s that exact look..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "沒錯！就是這個表情……"
L23_1.m_Talk_TWN = L24_1
L24_1 = "เออ นั่นแหละ ไอ้ท่าทางแบบนั้นแหละ..."
L23_1.m_Talk_THA = L24_1
L24_1 = "Đó, đúng vậy. Đúng là cái kiểu khuôn mặt đó..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "啊，没错。就是这个表情……"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ach, genau das, dieser Gesichtsausdruck ..."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Voilà ! C'est cette expression, sur ton visage..."
L23_1.m_Talk_FRA = L24_1
