L25_1 = 40
L24_1.m_Crash = L25_1
L25_1 = "순진한 척, 아무것도 모르는 척 하는 그 역겨운 표정……!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "純粋なふり、何も知らないふりをするその反吐が出そうな顔……！"
L24_1.m_Talk_JPN = L25_1
L25_1 = "That disgusting look of acting all innocent and pure...!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "一臉無辜，好像什麼都不知情的噁心嘴臉……！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ไอ้ท่าทางทำเป็นบริสุทธิ์เดียงสาน่าขยะแขยงนั่นแหละ...!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cái bộ dạng thanh khiết và ngây thơ kinh tởm đó...!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "假装纯真，假装毫不知情的那种恶心的表情……！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Dieses naive ... dieses nichtsahnend tuende Gesicht ...!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tu fais l'innocente, comme si tu ne comprenais pas... C'est écœurant !"
L24_1.m_Talk_FRA = L25_1
