L28_1 = "ALPHA_ACT3_INTERLUDE2@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3900304
L27_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "m_BGCrash"
L27_1[L28_1] = 10
L28_1 = "m_fBGCrashTime"
L27_1[L28_1] = 1
L27_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L28_1 = "너 정말 모르는 거니? 네 존재 자체가 우리 같은 평범한 사람들에게 얼마나 개 같은지?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あんた本当に知らないの？　あんたの存在自体が、私たちのような\n平凡な人間にとって、どれほどクソみたいなものなのか！"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Are you that clueless? Do you know how infuriating your existence is to people like me?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "你是真的不知道嗎？你的存在，對我們這種普通人而言有多討厭！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "นี่ไม่รู้หินรู้แดดอะไรเลยรึไง? ไม่รู้เหรอว่าไอ้การที่เธองอกหน้าอยู่บนโลกนี้มันทำให้คนแบบฉันโมโหขนาดไหน?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Mày không biết thật sao? Mày có biết sự tồn tại của mày khiến những người như tao cảm thấy thế nào không?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "你真的不知道吗？你的存在对我们这样平凡的人来说，是多么讨厌的事情？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Weißt du es wirklich nicht? Wie ätzend deine bloße Existenz für normale Leute wie mich ist?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ne te rends-tu donc pas compte comme les créatures comme toi peuvent être insupportables aux yeux de simples humains comme moi ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "ALPHA_ACT3_INTERLUDE2@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3900304
L28_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "m_BGCrash"
L28_1[L29_1] = 20
L29_1 = "m_fBGCrashTime"
L28_1[L29_1] = 1
L28_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L29_1 = "내가 받았어야 할 아빠의 사랑도! 그럴 때 항상 감싸 주던 큰 오빠도!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "私が受けるべきだった父さんの愛も！　いつも味方になってくれた兄さんも！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "The love I should’ve received from my father and brother!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "不只是爸爸的愛！還有那時候常常維護我的大哥！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ความรักที่ฉันควรได้จากพ่อจากพี่ชายน่ะ!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tình yêu mà đáng lẽ ra tao phải nhận được từ cha và anh trai của mình!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "父亲对我的爱！一直维护我的大哥！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Die Liebe meines Vaters, die mir zustand! Und mein großer Bruder, der mich immer in Schutz nahm!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Tu m'as volé tout ce que j'avais ! L'amour de mon père ! La tendresse de mon grand frère !"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "ALPHA_ACT3_INTERLUDE2@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3900304
L29_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "m_BGCrash"
L29_1[L30_1] = 30
L30_1 = "m_fBGCrashTime"
L29_1[L30_1] = 1
L29_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L30_1 = "그리고…… 내가 살면서 유일하게 자부심을 느꼈던 체스까지 네가 다 빼앗아 갔어!!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "そして……私の人生で唯一自負していたチェスまで、\nあんたが全部奪っていったわ！！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "And even chess... the one thing I was proud of...! You took everything away from me!!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "就連……我人生中唯一感到驕傲的西洋棋，你也要搶走！！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "หรือกระทั่งหมากรุก... อย่างเดียวที่ฉันภูมิใจ...! เธอเอาไปจากฉันหมดเลย!!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Và ngay cả cờ vua... điều mà tao vốn tự hào..! Mày đã lấy hết mọi thứ của tao!!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "还有……我生活中唯一值得骄傲的国际象棋！都被你夺走了！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Und ... mein Schachspiel, das mein einziger Stolz im Leben war, das alles hast du mir weggenommen!!!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Et... tu m'as même enlevé ma passion pour les échecs. La seule chose à laquelle j'étais douée !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
