L31_1[2] = L33_1
L30_1.m_Bounce = L31_1
L31_1 = "그 날 단 한 번의 대국으로!!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "あの日、たった一回の対局で！！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "All with just one game that day!!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "就在那天那場對弈中！！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ทั้งหมดในเกมเดียววันนั้น!!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tất cả chỉ với ván cờ ngày hôm đó!!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "就因为那天的对局！！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Durch diese einzige Partie an jenem Tag!!!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Et ça, en une seule partie !"
L30_1.m_Talk_FRA = L31_1
