L32_1 = "ALPHA_ACT3_INTERLUDE2@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3900304
L31_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_HATE"
L32_1 = "FX_CUTSCEN_NOISE_RUSTLE_03"
L31_1.m_StartFXSoundName = L32_1
L31_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L31_1.m_Pos = "C"
L32_1 = 40
L31_1.m_Crash = L32_1
L32_1 = "알아?! 그 날 나타난 워치도 나에겐 패배자의 낙인에 불과해!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "わかってるの！？　あの日現れたウォッチも、私には負け犬の烙印に\nすぎないのよ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You know what?! The Watch that appeared that day was nothing but a mark of failure!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "你知道嗎？！那天出現的能量環也是在告訴我，我是個失敗者！！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "รู้อะไรมั้ย?! วอตช์ที่โผล่มาวันนั้นน่ะมันก็แค่เครื่องหมายของความล้มเหลว!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Mày biết gì không?! Chiếc Đồng Hồ xuất hiện ngày hôm đó là dấu ấn thất bại nhục nhã!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "你知道吗？！那天出现的能量环，对我来说只是失败者的烙印而已！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Weißt du, selbst die Watch, die an jenem Tag erschien, ist für mich nur ein Brandmal eines Verlierers!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "La montre qui m'est apparue sur la peau ce jour-là... elle m'a rappelé tous les jours que j'étais une perdante !"
L31_1.m_Talk_FRA = L32_1
