L35_1 = "ALPHA_ACT3_INTERLUDE2@234#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 234
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3900304
L34_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_HATE"
L34_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L34_1.m_Pos = "L"
L35_1 = 40
L34_1.m_Crash = L35_1
L35_1 = "네 모가지를 졸라 비틀어 버리고 싶은 마음을 간신히 참고 있을 때!! 이 빌어먹을 게 나타났다고!!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "あんたを絞め殺したい気持ちを辛うじて我慢していた時！！\nこのクソみたいな時計が現れたの！！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Just when I was almost about to twist that neck of yours!! This damn thing stopped me!!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "我費多大的力，才忍住想要扭斷你脖子的衝動！該死的傢伙！！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เพราะตอนฉันจะหักคอแก!! ไอ้ของเวรนี่มันก็หยุดฉันไว้ไง!!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đến khi tao sắp vặn cổ mày!! Thứ chết tiệt đó lại ngăn cản tao!!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "在我强忍着想把你脑袋扭掉的冲动时！！这个东西就这么出现了！！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Als ich mit Mühen den Drang unterdrückt habe, dir den Hals umzudrehen, ist dieses verdammte Ding aufgetaucht!!!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "C'est quand j'étais à deux doigts de t'étrangler que cette fichue chose est apparue !"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "ALPHA_ACT3_INTERLUDE2@235#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3900304
L35_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L35_1.m_Pos = "L"
L35_1.m_Crash = 20
L36_1 = "……그런데 뭐? 많은 분들이 피해를 입어?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "……なのに、なに？　たくさんの方々が被害を受けた？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "And yet... You say that I made people suffer?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "……你還說什麼？有許多人因此受傷？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แล้ว... ยังมีหน้ามาบอกว่าฉันทำคนอื่นเป็นทุกข์อีกเหรอ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Vậy mà... Mày nói rằng tao khiến mọi người đau khổ ư?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "……可现在！你说有很多人因为我而受到了伤害？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "... Und du schwafelst noch von Leuten, die zu Schaden kamen?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "... Et tu oses me parler de préjudices ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
