L38_1 = 4
L39_1 = 0.15
L37_1[1] = L38_1
L37_1[2] = L39_1
L36_1.m_Bounce = L37_1
L37_1 = "나도 피해자야! 네가 난도질해 놓고! 갈기갈기 찢어 놓고는!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "私も被害者よ！　私の胸をえぐって！　身を裂くような思いをさせられて！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I’m also the victim here! You ripped my life to pieces!!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "我也是受害者好嗎！因為你的關係，害我失去多少東西！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฉันคนนี้ก็เหยื่อคนนึงเหมือนกันนะ! แกฉีกชีวิตฉันเป็นชิ้นๆ ไง!!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tao cũng là nạn nhân ở đây! Mày đã phá nát cuộc đời tao!!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "我也是受害者！我从那一天起，就已经死了，死了！你把我的生活撕了个粉碎！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich bin selbst ein Opfer! Du hast mich in Stücke gerissen! In tausend Fetzen!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Moi aussi je suis une victime ! Tu m'as brisée ! Tu m'as brisée en mille morceaux !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "ALPHA_ACT3_INTERLUDE2@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900304
L37_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
