L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L37_1.m_Pos = "L"
L38_1 = 40
L37_1.m_Crash = L38_1
L38_1 = "아무것도 모르는 척 불운한 공주님 행세를 하던 네가! 그딴 소리가 나와?!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "何も知らないふりをして不幸なお姫様を演じていたあんたに！\nあんたにそんなことを言う資格はない！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "So how dare you say that to me while you pretend to be the clueless damsel in distress!!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "而你竟然還裝得一副無辜樣，好像落難公主一樣！你憑什麼說那些話？！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แล้วยังมาทำตัวเป็นสาวน้อยไร้เดียงสาตีหน้าเศร้าเล่าความเท็จพูดจาแบบนั้นใส่ฉันอีก!!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Vậy nên, sao mày dám nói điều đó với tao trong khi mày giả vờ là nạn nhân vô tri!!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "一直装作毫不知情，扮演着不幸公主的你！好意思说出口吗？！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Und danach hast du dich als ahnungslose, unglückliche Prinzessin ausgegeben! Was erlaubst du dir?!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Arrête de faire la princesse inoccente qui ne fait rien ! Arrête ta comédie !"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
