L41_1 = "너에게서 내 걸 되찾으려면……. 상식적인 방법으로는 안 돼."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あんたから私のものを取り戻すには……常識的な方法じゃダメだったわ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "If I want to take back what’s mine from you... Conventional methods are useless."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我要從你身上奪回原本屬於我的東西……就不能用一般的方法。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ถ้าฉันจะเอาทุกอย่างคืนจากเธอนะ... วิธีโบราณๆ มันไม่ได้ผลหรอก"
L40_1.m_Talk_THA = L41_1
L41_1 = "Nếu tao muốn lấy lại những gì là của tao từ mày... Các phương pháp thông thường đều vô dụng."
L40_1.m_Talk_VTN = L41_1
L41_1 = "如果想从你那里夺回我失去的东西……常规的方法是行不通的。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wenn ich das Meinige von dir zurückholen will ... verlangt es außerordentliche Methoden."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Pour reprendre ce que tu m'as pris... J'ai été obligée d'avoir recours à ces méthodes."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
