L41_1.m_Crash = L42_1
L42_1 = "세상 전부를 베팅할 각오가 없으면 안 된다고!!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "世界全部を賭ける覚悟がないとダメだったの！！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I need to put everything on the line just to have my shot!!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "沒有賭上全世界的決心是不行的！！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฉันต้องยอมเอาทุกอย่างไปเสี่ยงเพื่อสร้างโอกาส!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tao cần phải sắp xếp mọi thứ để đi đến kết quả cuối cùng!!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "没有赌上全部的觉悟，就不可能成功！！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Es geht nur, wenn ich die ganze Welt aufs Spiel setze!!!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je devais être prête à mettre en jeu le monde entier !"
L41_1.m_Talk_FRA = L42_1
