L45_1 = "ALPHA_ACT3_INTERLUDE2@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 244
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900304
L44_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L44_1.m_Pos = "R"
L45_1 = "고모님 말씀대로……. 저는 고모님이 얼마나 아파했는지 이해할 수 없을지도 몰라요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "叔母様のおっしゃるとおり……私は叔母様がどれほど辛かったのか、\n理解できないかもしれません。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "As you said, I may not understand the pain you've gone through."
L44_1.m_Talk_ENG = L45_1
L45_1 = "姑姑說的沒錯……或許我確實無法理解姑姑的痛苦，"
L44_1.m_Talk_TWN = L45_1
L45_1 = "อย่างที่น้าว่าแหละค่ะ หนูอาจไม่เข้าใจความเจ็บปวดที่น้าเจอมา"
L44_1.m_Talk_THA = L45_1
L45_1 = "Như cô đã nói, cháu có thể không hiểu sự đau khổ mà cô phải chịu."
L44_1.m_Talk_VTN = L45_1
L45_1 = "就如姑姑所说……我没办法理解姑姑有多么难受。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "So wie Sie schon sagten... kann ich wohl niemals nachvollziehen, welchen Schmerz Sie erlitten haben."
L44_1.m_Talk_DEU = L45_1
L45_1 = "C'est vrai... Je ne peux pas savoir ce que vous avez éprouvé mais..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ALPHA_ACT3_INTERLUDE2@245#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 245
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3900304
