L45_1.m_Face = "UNIT_HATE"
L45_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L45_1.m_Pos = "R"
L46_1 = "하지만 한 가지는 알아요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ですが、一つだけわかることがあります。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "But I know this."
L45_1.m_Talk_ENG = L46_1
L46_1 = "但我很清楚一件事，"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แต่หนูรู้เรื่องนี้ค่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Nhưng cháu biết điều này."
L45_1.m_Talk_VTN = L46_1
L46_1 = "但我清楚一件事。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Aber Eines weiß ich."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je suis sûre d'une chose."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
