L46_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L46_1.m_Pos = "R"
L46_1.m_Crash = 10
L47_1 = "고모님이 지금껏 저지르신 행동은…… 평범하지도, 올바르지도 않아요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "叔母様が今まで犯した行動は……普通でも正しくもありません。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "The actions you’ve committed... they cannot be justified no matter what."
L46_1.m_Talk_ENG = L47_1
L47_1 = "就是姑姑至今的所作所為……不是一般人該有的行為，完全不正當！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "สิ่งที่อาทำลงไป... ไม่ว่ายังไงก็ไม่มีทางชอบธรรมได้เลย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Những hành động mà cô đã phạm phải... chúng không thể bào chữa được."
L46_1.m_Talk_VTN = L47_1
L47_1 = "姑姑你至今为止的行为……是不对的。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Die Sachen, die Sie bisher angerichtet haben ... sie waren weder normal noch richtig."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Vos actes ne sont pas ordinaires, et ils ne sont pas justes."
L46_1.m_Talk_FRA = L47_1
