L49_1.m_Pos = "L"
L50_1 = "그래. 하긴, 사람 손에서 만들어진 주제에 사람 마음을 어떻게 알겠어."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そうね。確かに、人間の手で作られたものに人間の心なんか\nわかるはずがないわ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "You’re right. How can an experiment like you understand what it’s like to be human."
L49_1.m_Talk_ENG = L50_1
L50_1 = "也是，藉由人手所造出來的東西，怎麼會理解人類的心情呢？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "นั่นสินะ ของทดลองอย่างเธอมันจะไปเข้าใจได้ยังไงว่ามนุษย์เขาเป็นยังไงกัน"
L49_1.m_Talk_THA = L50_1
L50_1 = "Đúng lắm. Một vật thí nghiệm như mày sao có thể hiểu được cuộc sống của con người là như thế nào."
L49_1.m_Talk_VTN = L50_1
L50_1 = "是啊。作为被人类创造出来的东西，你怎么可能理解呢。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ja, okay. Wie würde ein menschengemachtes Wesen auch einen Menschen nachvollziehen können?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Bah. Comment une créature créée de toutes pièces pourrait comprendre ce que ressentes les humains ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
