L3_1 = "ALPHA_ACT3_INTERLUDE2@252#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 252
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3900304
L2_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L2_1.m_bWaitClick = true
