L2_1.m_Face = "UNIT_SERIOUS"
L2_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L2_1.m_Pos = "C"
L3_1 = "오라버니는 너 같은 괴물은 이 세상에서 없어져야 한다고 믿었어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "副会長だった兄さんは、あんたみたいな化け物がこの世から消えるべきだと信じていたわ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "My brother believes that monsters like you shouldn’t exist in this world."
L2_1.m_Talk_ENG = L3_1
L3_1 = "大哥一直認為，像你這種怪物，根本就不該存在於這個世界上。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "พี่ชายฉันน่ะเชื่อว่าตัวประหลาดอย่างเธอมันไม่ควรมีในโลก"
L2_1.m_Talk_THA = L3_1
L3_1 = "Anh trai tao tin rằng những con quái vật như mày không nên tồn tại trên thế giới này."
L2_1.m_Talk_VTN = L3_1
L3_1 = "哥哥认为像你这样的怪物就该从世界上消失。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Mein Bruder war der Ansicht, dass ein Monster wie du aus der Welt zu verschwinden hat."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Mon grand frère disait qu'un monstre comme toi ne devait pas exister dans ce monde."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "ALPHA_ACT3_INTERLUDE2@253#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 253
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3900304
L3_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L3_1.m_Pos = "C"
L4_1 = "그런데 내 생각은 좀 달라."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "でも私の考えは違う。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "But I have a different opinion."
L3_1.m_Talk_ENG = L4_1
L4_1 = "但我的想法和大哥不一樣。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แต่ฉันไม่คิดงั้นนะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nhưng tao lại có ý kiến khác."
L3_1.m_Talk_VTN = L4_1
L4_1 = "但我的想法却不同。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Aber ich denke da etwas anders."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Mais je ne suis pas tout à fait d'accord avec lui."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "ALPHA_ACT3_INTERLUDE2@254#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 254
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3900304
L4_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
