L4_1.m_Face = "UNIT_IDLE"
L4_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L4_1.m_Pos = "C"
L5_1 = "판돈을 잃었으면, 잃은 만큼 따고 자리에서 일어나야지."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "賭け金を失ったなら、失った分を取り戻してから席を立たないと。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "If you lose a bet, you double down and recover your loses before leaving the table."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我認為，從哪裡賭輸，就要從哪裡贏回來！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "คนเราถ้าแพ้พนัน ก็ต้องลงเพิ่มไปสองเท่าเพื่อเอาคืนให้หมดก่อนเลิกเล่น"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nếu mày thua cược, mày đặt gấp đôi và lấy lại số tiền bị thua trước khi rời bàn."
L4_1.m_Talk_VTN = L5_1
L5_1 = "如果失去了赌注，就该在失去的地方重新站起来。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Wenn man das Spielgeld verspielt hat, muss man sich den Betrag wieder erspielen und dann aufstehen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Quand on perd au jeu, il suffit de regagner ses gains et de partir."
L4_1.m_Talk_FRA = L5_1
