L7_1[L8_1] = L9_1
L8_1 = "m_CharScaleTime"
L9_1 = 0.01
L7_1[L8_1] = L9_1
L8_1 = "겨우 내 정체를 밝힌 걸로 체크메이트를 외치려고 했다면 오산이야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私の正体を明かした程度でチェックメイトをしたつもりなら大間違いよ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "If you think it’s checkmate just because you’ve exposed me, you’re making a big mistake."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你以為知道我的身分，就可以喊將軍嗎？沒這麼容易的事！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ถ้าคิดว่านี่รุกจนแล้วเพราะเปิดโปงฉันได้ เธอก็พลาดใหญ่หลวงแล้ว"
L7_1.m_Talk_THA = L8_1
L8_1 = "Nếu mày tưởng vạch trần tao là chiếu tướng, mày đang phạm phải sai lầm lớn."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你以为靠揭露我的真实身份，就能把我将死的话，就失算了。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Du hast dich geirrt, als du Schachmatt rufen wolltest, nur weil du meine Identität enthüllt hast."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Alors quoi, tu as dévoilé mon identité, et après ? « Échec et mat », peut-être ? TU te trompes."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
