L8_1[L9_1] = L10_1
L9_1 = "m_CharScaleTime"
L10_1 = 0.01
L8_1[L9_1] = L10_1
L9_1 = "이번엔 나도 만반의 준비를 갖췄으니까."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "今回は私も万全の準備を整えたからね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Because I came prepared as well."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我這次可是有做好萬全的準備！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เพราะฉันไม่ได้มาเล่นๆ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Bởi vì tao cũng đã chuẩn bị sẵn sàng."
L8_1.m_Talk_VTN = L9_1
L9_1 = "因为这次我已经做好了完美的准备。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Denn diesmal bin ich vorbereitet."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Parce que cette fois-ci, je suis prête."
L8_1.m_Talk_FRA = L9_1
