L9_1[L10_1] = L11_1
L10_1 = "m_CharScaleTime"
L11_1 = 0.01
L9_1[L10_1] = L11_1
L10_1 = "그 날 대국은 쓸데없이 너무 공정했다고 생각하거든……!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "あの日の対局は無駄に公正すぎたと思ったのよ……！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I always thought the game we played was overly fair...!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "那天的對弈都怪我手腳太乾淨……！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันคิดมาตลอดนะว่าที่เราเล่นกันตอนนั้นมันแฟร์เกิน...!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tao luôn nghĩ trò chơi mà chúng ta chơi là quá công bằng...!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "我觉得那天的对局过于公平了，这也太没有意义了，不是吗……！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ich finde, dass unsere Partie damals unnötig fair war ...!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "J'ai été un peu trop loyale pour rien lors de notre dernière partie...!"
L9_1.m_Talk_FRA = L10_1
