L12_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L11_1.m_StartFXSoundName = L12_1
L11_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L12_1 = "R_F_C"
L11_1.m_Pos = L12_1
L12_1 = "저 애 뭐야? 갑자기 남자 목소리로 바뀌었어!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "あの子なんなの？　急に男の声に変わった！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "What the heck? Her voice changed into a man’s!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "她是怎樣？怎麼突然變成男聲？！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "อะไรเนี่ย? เสียงเธอเปลี่ยนเป็นผู้ชายแล้ว!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cái quái gì vậy? Giọng nói của cô ta đã thay đổi thành một người đàn ông!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "这是怎么回事？突然变成了男人的声音！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Was zum Teufel? Ihre Stimme ist auf einmal männlich!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "C'est quoi ça encore ? Pourquoi elle a la voix d'un homme maintenant ?"
L11_1.m_Talk_FRA = L12_1
