L15_1.m_Bounce = L16_1
L16_1 = "<color=#ffd34c>파사의 목소리</color> 님?!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "<color=#ffd34c>破邪の声</color>様！？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Mr. <color=#ffd34c>Voice of Evil Eradication</color>?!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "<color=#ffd34c>破邪之聲</color>？！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "คุณ<color=#ffd34c>เสียงแห่งการกวาดล้างความชั่วร้าย</color>เหรอ?!"
L15_1.m_Talk_THA = L16_1
L16_1 = "<color=#ffd34c>Tiếng Nói Trừ Gian Diệt Ác</color>?!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "<color=#ffd34c>破邪之声</color>？！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Die <color=#ffd34c>Stimme des Bekämpfers des Bösen</color>?!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Voix de l'éradication du MalC'est la <color=#ffd34c>Voix de l'éradication du Mal</color> ?"
L15_1.m_Talk_FRA = L16_1
