L17_1 = "ALPHA_ACT3_INTERLUDE2@266#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 266
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3900304
L16_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_HATE"
L16_1.m_CharStrID = "CHOI_ALPHA_NULL_SHORT"
L16_1.m_Pos = "L"
L17_1 = "네가 추종하던 그 수상한 목소리라고? 그렇다면 처음부터 손바닥 위였다는 건가!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "君が従っていたあの怪しい声だと？\nつまり最初から掌の上だったということか！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "That’s the weird voice you were following? Then that means she’s been playing you all this time!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "就是你說的那個詭異的聲音？所以從一開始就是算計好的嗎？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เสียงประหลาดๆ ที่เจ้าเชื่อฟังนั่นนะเหรอ? งั้นก็แปลว่านางหลอกเจ้ามาตลอดเลยนะสิ!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Đó là giọng nói kỳ lạ mà em luôn nghe theo đấy ư? Vậy thì điều đó có nghĩa là suốt thời gian qua cô ta đã chơi em!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "是你追随的那个奇怪的声音？也就是说，你一直被别人玩弄于股掌之中！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das ist diese suspekte Stimme, die du befolgt hast? Dann waren wir ja von Anfang an im Trick gefangen!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "C'est la voix que tu suivais ? Ça veut dire qu'elle te manipulait depuis le début ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
