L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3900304
L18_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "UNIT_SERIOUS2"
L18_1.m_Face = L19_1
L18_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L18_1.m_Pos = "C"
L19_1 = "m_CharScale"
L20_1 = {}
L21_1 = 1.3
L22_1 = 1.3
L20_1[1] = L21_1
L20_1[2] = L22_1
L18_1[L19_1] = L20_1
L19_1 = "m_CharScaleTime"
L20_1 = 0.01
L18_1[L19_1] = L20_1
L19_1 = "흥. 수상쩍은 설정에 혹하는 팔랑귀라 꽤 잘 써먹었지."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ふん。怪しい設定に従うような性格で、上手いこと使えたわ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Hmpf. I had my fun swaying that gullible kid around with what she wanted to hear."
L18_1.m_Talk_ENG = L19_1
L19_1 = "哼，誰叫她耳根子軟，才會被人利用！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เฮอะ การปั่นหัวนังเด็กหลอกง่ายนั่นให้เต้นไปตามสิ่งที่ตัวเองอยากได้ยินนี่สนุกเป็นบ้า"
L18_1.m_Talk_THA = L19_1
L19_1 = "Hmpf. Ta đã rất vui khi xoay con bé cả tin ấy như chong chóng với những điều nó muốn nghe."
L18_1.m_Talk_VTN = L19_1
L19_1 = "哼。轻信奇怪设定的糊涂蛋，我只是利用了一下而已。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Hmpf. Das hat gut geklappt, weil sie so leichtgläubig war."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Hé hé. Tu m'as bien été utile. Je ne pensais pas que tu allais tomber dans le panneau aussi facilement avec ce dispositif étrange."
L18_1.m_Talk_FRA = L19_1
