L22_1 = "ALPHA_ACT3_INTERLUDE2@271#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 271
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3900304
L21_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "UNIT_SERIOUS2"
L21_1.m_Face = L22_1
L21_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L21_1.m_Pos = "L"
L22_1 = "하지만 여기까지야. 괜히 더 들쑤시고 다니면 귀찮아지거든."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "でもここまでよ。これ以上勝手にかき回されたら面倒だから。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "But fun’s over now. It’ll only get bothersome if she starts poking around in places where she shouldn’t be."
L21_1.m_Talk_ENG = L22_1
L22_1 = "不過就到此為止，再繼續糾纏下去只會更麻煩。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "แต่พอแล้ว ถ้าเธอยังเที่ยวสอดรู้ในเรื่องไม่ควรแบบนี้มันก็รังแต่จะน่ารำคาญ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nhưng bây giờ trò vui đã kết thúc. Cô ta cứ chõ mũi vào khắp mọi nơi, kể cả những chỗ cô ta không nên tới, việc đó thật chẳng hay ho chút nào."
L21_1.m_Talk_VTN = L22_1
L22_1 = "不过到此为止了。继续让你乱跑的话，会让人很头疼的。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Aber bis hierhin. Man sollte irgendwann einen Strich ziehen, sonst geht es übel aus."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Mais on s'arrête là. J'en ai assez de me trimballer ce machin partout avec moi."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "ALPHA_ACT3_INTERLUDE2@272#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 272
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3900304
L22_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L22_1.m_Pos = "L"
L23_1 = "뒤늦게 내 흉내를 내려던 오빠처럼 말이야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "後から私の真似をしようとした兄さんのようにね。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Just like how my brother tried to act like me."
L22_1.m_Talk_ENG = L23_1
L23_1 = "就跟我那個學人精哥哥一樣！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เหมือนที่พี่ชายฉันพยายามเลียนแบบฉันนั่นแหละ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cũng giống như cách mà anh trai ta đã cố gắng để trở nên giống ta."
L22_1.m_Talk_VTN = L23_1
L23_1 = "就像后知后觉，想要模仿我的哥哥一样。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wie für meinen Bruder, der mich letztendlich imitieren wollte."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Comme mon grand frère qui voulait tant m'imiter."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "ALPHA_ACT3_INTERLUDE2@273#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 273
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3900304
L23_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Crash = 10
L24_1 = "고모님, 그 목소리는……. 할아버님 것이잖아요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "叔母様、その声は……お祖父様のものでは？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That voice... Isn’t that Grandfather’s voice?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "姑姑，你那不是……爺爺的聲音嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "เสียงนั่น... นั่นมันเสียงของคุณปู่ไม่ใช่เหรอคะ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Giọng nói đó... Đó chẳng phải là giọng của Ông Nội sao?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "姑姑，那个声音……是爷爷的吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Tante, diese Stimme ist doch ... von Großvater?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Mais c'est la voix de... Grand-père !"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
