L26_1 = "ALPHA_ACT3_INTERLUDE2@275#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 275
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3900304
L25_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "UNIT_SERIOUS2"
L25_1.m_Face = L26_1
L25_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L25_1.m_Pos = "C"
L25_1.m_Crash = 10
L26_1 = "바로 맞췄구나. 역시 지아다워."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そうよ。さすがだわ、ユイちゃん。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Nothing gets past you, Jia."
L25_1.m_Talk_ENG = L26_1
L26_1 = "猜沒錯，真不愧是小佳！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่มีอะไรเล็ดรอดสายตาเธอไปได้เลยนะเจีย"
L25_1.m_Talk_THA = L26_1
L26_1 = "Khá tinh tường đấy, Jia."
L25_1.m_Talk_VTN = L26_1
L26_1 = "你猜对了。不愧是小佳。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Du hast es sofort erraten. Sieht dir ähnlich."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Tu as tout de suite reconnu. Ça ne m'étonne pas de toi, Jia."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "ALPHA_ACT3_INTERLUDE2@276#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 276
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3900304
L26_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L26_1.m_Pos = "C"
L27_1 = "그러면 정식으로 다시 소개해야겠구나."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "それでは改めて紹介しよう。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Now, allow me to introduce myself again."
L26_1.m_Talk_ENG = L27_1
L27_1 = "那我就正式跟大家介紹一下，"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ทีนี้ก็ขอฉันแนะนำตัวอีกรอบนะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Bây giờ, để ta tự giới thiệu một lần nữa."
L26_1.m_Talk_VTN = L27_1
L27_1 = "那么我正式介绍一下吧。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Dann stelle ich mich offiziell vor."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Laissez-moi de nouveau me présenter."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "ALPHA_ACT3_INTERLUDE2@277#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 277
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3900304
L27_1.m_CutScenStrID = "ALPHA_ACT3_INTERLUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L27_1.m_Pos = "C"
L28_1 = "그래, 네 말대로 나는 방탕하단 이유만으로 집안에서 내쫓겼던 네 고모이자……."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "そう。あんたの言うとおり、私は道楽娘だという理由だけで\n家から追い出されたあんたの叔母であり……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Yes, I am your aunt. The black sheep of the family who got exiled for leading a life of debauchery..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "沒錯，如你所說，我就是那個因為不學好，而被趕出家門的姑姑……"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ใช่ ฉันคืออาของเธอ แกะดำของตระกูลผู้ถูกเนรเทศไปใช้ชีวิตเสเพล..."
L27_1.m_Talk_THA = L28_1
L28_1 = "Đúng, tao là cô của mày. Con cừu đen của gia đình bị lưu đày vì sống một cuộc đời sa đọa..."
L27_1.m_Talk_VTN = L28_1
L28_1 = "我不仅仅是你口中那个因纨绔行径被逐出家门的姑姑……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ja, ich bin deine Tante, die aufgrund eines ausschweifenden Lebens aus der Familie vertrieben wurde ..."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Je suis, comem tu l'as dit, ta tante qui s'est faite chasser pour une raison crapuleuse . Mais je suis aussi..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "ALPHA_ACT3_INTERLUDE2@278#Talk"
